window.DGNL_CHUYEN_DE["HinhHocKhongGian"] = [{"noiDungChung": null, "cauHoi": [{"question": "Cho hình lập phương $ABCD.A'B'C'D'$.  Góc giữa hai đường thẳng $AB$ và $B'D'$ bằng<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "choices": ["$30^\\circ $", "$135^\\circ $", "$45^\\circ $", "$90^\\circ $"], "correctIndex": 2, "explain": "Vì $ABCD.A'B'C'D'$ là hình lập phương nên ta có $AB\\parallel A'B'$.<br>Suy ra  $$ \\left(AB,B'D'\\right)=\\left(A'B',B'D'\\right)=\\widehat{A'B'D'}=45^\\circ .$$<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử, Chuyên ĐH Vinh, Nghệ An, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình lập phương $ABCD.A'B'C'D'$. <br>Số đo góc giữa hai đường thẳng $AC$ và $A'D$ bằng<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "choices": ["$30^\\circ$", "$45^\\circ$", "$60^\\circ$", "$90^\\circ$"], "correctIndex": 2, "explain": "Gọi cạnh của hình lập phương là $a$.<br>Vì $A'C'\\parallel AC$ nên $\\widehat{(AC,A'D)}=\\widehat{(A'C',A'D)}$.<br>Ta có $A'C'=A'D=DC'=\\sqrt{DD'^2+D'C'^2}=a\\sqrt{2}$ nên $\\triangle A'DC'$ đều hay $\\widehat{(A'D,A'C')}=\\widehat{DA'C'}=60^\\circ$.<br>Vậy $\\widehat{(AC,A'D)}=60^\\circ$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Giữa học kì 2, Sở giáo dục Bắc Giang - Lần 1, 2020-2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình lập phương $ABCD.A'B'C'D'$. Góc giữa đường thẳng $AB$ và $B'D'$ bằng<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.35, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\\draw (0,0)-- (0,5)--(3,8)--(8,8)--(5,5)--(0,5);\n\t\t\t\\draw (0,0)-- (5,0)--(8,3);\n\t\t\t\\draw (5,0)--(5,5);\n\t\t\t\\draw (8,3)--(8,8);\n\t\t\t\\draw (3,8)--(5,5);\n\t\t\t\\draw [dashed] (0,0)-- (3,3)--(8,3);\n\t\t\t\\draw [dashed] (3,3)--(3,8);\n\t\t\t\\draw [dashed] (3,3)--(5,0);\n\t\t\t\n\t\t\t\\filldraw [black] (0,0) circle (1pt) node[left] {$A$};\n\t\t\t\\filldraw [black] (3,3) circle (1pt) node[left] {$B$}; \n\t\t\t\\filldraw [black] (8,3) circle (1pt) node[right] {$C$};\n\t\t\t\\filldraw [black] (5,0) circle (1pt) node[right] {$D$};\n\t\t\t\\filldraw [black] (0,5) circle (1pt) node[left] {$A'$};\n\t\t\t\\filldraw [black] (3,8) circle (1pt) node[left] {$B'$}; \n\t\t\t\\filldraw [black] (8,8) circle (1pt) node[right] {$C'$};\n\t\t\t\\filldraw [black] (5,5) circle (1pt) node[right] {$D'$};\n\t\t\\end{tikzpicture}</script></div>", "choices": ["$90^{\\circ}$", "$45^{\\circ}$", "$30^{\\circ}$", "$135^{\\circ}$"], "correctIndex": 1, "explain": "Ta có $B'D' \\parallel BD$. <br>Suy ra $\\left( B'D',AB \\right)=\\left( BD,AB \\right)=\\widehat{ABD}=45^{\\circ}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.5, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\\draw (0,0)-- (0,5)--(3,8)--(8,8)--(5,5)--(0,5);\n\t\t\t\t\\draw (0,0)-- (5,0)--(8,3);\n\t\t\t\t\\draw (5,0)--(5,5);\n\t\t\t\t\\draw (8,3)--(8,8);\n\t\t\t\t\\draw (3,8)--(5,5);\n\t\t\t\t\\draw [dashed] (0,0)-- (3,3)--(8,3);\n\t\t\t\t\\draw [dashed] (3,3)--(3,8);\n\t\t\t\t\\draw [dashed] (3,3)--(5,0);\n\t\t\t\t\n\t\t\t\t\\filldraw [black] (0,0) circle (1pt) node[left] {$A$};\n\t\t\t\t\\filldraw [black] (3,3) circle (1pt) node[left] {$B$}; \n\t\t\t\t\\filldraw [black] (8,3) circle (1pt) node[right] {$C$};\n\t\t\t\t\\filldraw [black] (5,0) circle (1pt) node[right] {$D$};\n\t\t\t\t\\filldraw [black] (0,5) circle (1pt) node[left] {$A'$};\n\t\t\t\t\\filldraw [black] (3,8) circle (1pt) node[left] {$B'$}; \n\t\t\t\t\\filldraw [black] (8,8) circle (1pt) node[right] {$C'$};\n\t\t\t\t\\filldraw [black] (5,5) circle (1pt) node[right] {$D'$};\n\t\t\\end{tikzpicture}</script></div>", "nguon": "Thi thử, Sở GD và ĐT - Nghệ An - Lần 03, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình chóp $S.ABC$ có $BC=a\\sqrt{2}$, các cạnh còn lại đều bằng $a$. <br>Góc giữa hai đường thẳng $SB$ và $AC$ bằng<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "choices": ["$60^{\\circ}$", "$30^{\\circ}$", "$90^{\\circ}$", "$45^{\\circ}$"], "correctIndex": 0, "explain": "Để ý thấy $BC^2=SB^2+SC^2$ nên $\\triangle SBC$ vuông tại $S$.<br>Ta có $SA=SB=AB=a$ nên $\\triangle SAB$ là tam giác đều.<br>Khi đó   \\begin{eqnarray*}  \\overrightarrow{SB}\\cdot\\overrightarrow{AC}&=&\\overrightarrow{SB}\\cdot\\left(\\overrightarrow{SC}-\\overrightarrow{SA}\\right)<br>&=& \\overrightarrow{SB}\\cdot\\overrightarrow{SC}-\\overrightarrow{SB}\\cdot\\overrightarrow{SA}<br>&=& 0-SB\\cdot SA\\cdot\\cos\\widehat{ASB}<br>&=&-\\dfrac{a^2}{2}.  \\end{eqnarray*} \\noindent\\vspace{0.2cm}<br>Suy ra $\\cos\\left(\\overrightarrow{SB},\\overrightarrow{AC}\\right)=\\dfrac{\\overrightarrow{SB}\\cdot\\overrightarrow{AC}}{SB\\cdot AC}=-\\dfrac{1}{2}\\Rightarrow \\left(\\overrightarrow{SB},\\overrightarrow{AC}\\right)=120^\\circ$.<br>Vậy $(SB,AC)=180^\\circ-120^\\circ=60^\\circ$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử tháng 3, trường THPT Gia Viễn A-Ninh Bình, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình lăng trụ tam giác đều cạnh đáy bằng $a$, cạnh bên có độ dài bằng $a\\sqrt{2}$. Tính góc giữa hai đường thẳng $AB'$ và $BC'$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.4, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\\draw (-2,2) node [left] {$ A' $} -- (0,0) node [below] {$ B' $}-- (4,2) node [right]{$ C' $} -- (4,7) node [right] {$ C $}-- (0,5) node [above] {$ B $}-- (-2,7) node [left]{$ A $} -- (4,7);\n\t\t\t\t\\draw (-2,2) -- (-2,7);\n\t\t\t\t\\draw (0,0) -- (0,5);\n\t\t\t\t\\draw [dashed] (-2,2)--(4,2);\n\t\t\t\t\\draw (-2,7) -- (0,0);\n\t\t\t\t\\draw (0,5) -- (4,2);\n\t\t\t\\end{tikzpicture}</script></div>", "choices": ["$60^{\\circ} $", "$120^{\\circ} $", "$90^{\\circ} $", "$30^{\\circ} $"], "correctIndex": 0, "explain": "Ta có  \\[\n\t\t\t\\begin{aligned}\n\t\t\t\t\\overrightarrow{AB'}\\cdot \\overrightarrow{BC'}\n\t\t\t\t&=\\overrightarrow{AB'}\\left( \\overrightarrow{AC'}-\\overrightarrow{AB} \\right) \\\\\n\t\t\t\t&=\\dfrac{AB'^2+AC'^2-B'C'^2}{2}-\\dfrac{AB'^2+AB^2-BB'^2}{2} \\\\\n\t\t\t\t&=\\dfrac{3a^2-a^2}{2}-\\dfrac{a^2-2a^2}{2} \\\\\n\t\t\t\t&=\\dfrac{3a^2}{2}.\n\t\t\t\\end{aligned}\\]  Do đó $\\cos \\left( AB',BC' \\right)=\\left| \\cos \\left( \\overrightarrow{AB'},\\overrightarrow{BC'} \\right) \\right|=\\dfrac{\\left| \\overrightarrow{AB'}\\cdot \\overrightarrow{BC'} \\right|}{AB'\\cdot BC'}=\\dfrac{\\tfrac{3a^2}{2}}{a\\sqrt{3}\\cdot a\\sqrt{3}}=\\dfrac{1}{2}$.<br>Vậy góc giữa hai đường thẳng $AB'$ và $BC'$ bằng $60^{\\circ} $.", "nguon": "Thi thử L3, Chuyên Quang Trung, Bình Phước, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy là hình vuông cạnh $a$, $SA=a\\sqrt{3}$, đường thẳng $SA$ vuông góc với mặt $(ABCD)$. Góc giữa đường thẳng $SD$ và $(SAB)$ là", "choices": ["$30^\\circ$", "$90^\\circ$", "$60^\\circ$", "$45^\\circ$"], "correctIndex": 0, "explain": "Ta có $DA\\perp (SAB)$ nên góc giữa $SD$ và $(SAB)$ là $\\widehat{ASD}$.<br>Lại có $\\tan\\widehat{ASD}=\\dfrac{AD}{SA}=\\dfrac{a}{a\\sqrt{3}}=\\dfrac{\\sqrt{3}}{3}$.<br>Suy ra $\\widehat{ASD}=30^\\circ$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Đề thi thử lần 1 THPT Trần Nhân Tông - Quảng Ninh, 2020-2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp tứ giác đều $S.ABCD$ có $AB=a$ và $SA=2a$. Tính tang của góc giữa $SA$ và $(ABCD)$.", "choices": ["$\\sqrt{5}$", "$\\dfrac{\\sqrt{5}}{2}$", "$\\sqrt{3}$", "$\\sqrt{7}$"], "correctIndex": 3, "explain": "Vì $S.ABCD$ là hình chóp đều nên $ABCD$ là hình vuông. Gọi $O$ là tâm hình vuông $ABCD$, khi đó $SO\\perp (ABCD)$. Góc giữa $SA$ và $(ABCD)$ là góc $(SA,OA)$.<br>Lại do tam giác $SOA$ vuông tại $O$ nên $(SA,OA)=\\widehat{SAO}$. Mà $SA=2a$, $OA=\\dfrac{1}{2}AC=\\dfrac{a\\sqrt{2}}{2}$ nên  \\[\\tan(SA,(ABCD))=\\tan\\widehat{SAO} = \\dfrac{SO}{AO} = \\dfrac{\\sqrt{SA^2-AO^2}}{AO} = \\sqrt{7}.\\]<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Đề GHK2 - Trường THPT Chuyên Vĩnh Phúc, năm học 2020 - 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy là hình vuông cạnh $a$, $SA \\perp (ABCD)$ và $SB = 2a$. Góc giữa $SB$ và $(ABCD)$ là", "choices": ["$60^\\circ $", "$ 45^\\circ $", "$ 90^\\circ $", "$30^\\circ$"], "correctIndex": 0, "explain": "Do $SA \\perp (ABCD)$ nên $A$ là hình chiếu vuông góc của $S$ lên $(ABCD)$.<br>Khi đó góc giữa $SB$ và $(ABCD)$ là $\\widehat{SBA}$.<br>Xét tam giác $SAB$ vuông tại $A$, ta có  $$\\cos \\widehat{SBA} = \\dfrac{AB}{SB} = \\dfrac{1}{2} \\Rightarrow \\widehat{SBA} = 60^\\circ.$$  Vậy góc giữa đường thẳng $SB$ và $(ABCD)$ là $60^\\circ$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử, THPT Nguyễn Đăng Đạo - Bắc Ninh"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABC$ có đáy là tam giác vuông cân tại $B$ và $SA\\perp(ABC)$. Biết rằng $AB=a$, $SC=a\\sqrt{5}$. Khi đó, góc giữa đường thẳng $SB$ và mặt phẳng $(ABC)$ bằng", "choices": ["$90^\\circ$", "$45^\\circ$", "$30^\\circ$", "$60^\\circ$"], "correctIndex": 3, "explain": "Hình chiếu vuông góc của $SB$ lên $(ABC)$ là $AB$.<br>Khi đó $(SB,(ABC))=(SB,AB)=\\widehat{SBA}$.<br>Do tam giác $ABC$ vuông cân tại $B$ nên $AC=AB\\cdot\\sqrt{2}=a\\sqrt{2}$.<br>Xét tam giác $SAC$ vuông tại $A$, có  \\[SA=\\sqrt{SC^2-AC^2}=\\sqrt{5a^2-2a^2}=a\\sqrt{3}.\\]  Xét tam giác vuông $SAB$, có  \\[\\tan B=\\dfrac{SA}{AB}=\\dfrac{a\\sqrt{3}}{a}=\\sqrt{3}.\\]  Suy ra $\\widehat{SBA}=60^\\circ$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[line cap=round,line join=round,font=\\footnotesize,>=stealth,scale=1]\n\t\t\t\t\t\\fill (0,0) coordinate [label=above left:$A$] (A) circle(1pt)\n\t\t\t\t\t(0:3) coordinate [label=below right:$B$] (B) circle(1pt)\n\t\t\t\t\t(90:2) coordinate [label=above right:$S$] (S) circle(1pt)\n\t\t\t\t\t(-40:2) coordinate [label=below right:$C$] (C) circle(1pt);\n\t\t\t\t\t\\draw (A)--(S)--(B)--(C)--(A) (S)--(C);\n\t\t\t\t\t\\draw[dashed] (A)--(B);\n\t\t\t\\end{tikzpicture}</script></div>", "nguon": "Đề thi thử Lần 1 THPT Nguyễn Thị Minh Khai - Hà Nội, năm 2020 - 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình chóp $S . A B C D$ có đáy là hình vuông cạnh $a$, $S A$ vuông góc với mặt phẳng đáy và $S A=a \\sqrt{2}$. Góc giữa đường thẳng $S C$ và $(A B C D)$ bằng", "choices": ["$45^{\\circ}$", "$90^{\\circ}$", "$60^{\\circ}$", "$30^{\\circ}$"], "correctIndex": 0, "explain": "Ta có $SA \\perp (ABCD)$ nên đường thẳng $AC$ là hình chiếu vuông góc của đường thẳng $SC$ trên $(ABCD)$. <br>Do đó $(SC,(ABCD)) = (SC,AC) = \\widehat{SCA}$. <br>Mặt khác do $SA=AC=a\\sqrt{2}$ nên tam giác $SAC$ vuông cân tại $A$. <br>Suy ra $(SC,(ABCD)) = 45^\\circ$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử lần 1, Chuyên Trần Phú Hải Phòng, 2020-2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình lăng trụ đứng $ ABC.A'B'C' $ có đáy $ ABC $ là tam giác vuông cân tại $ A $, $ AB=AA'=a $. Tang của góc giữa $ BC' $ và mặt phẳng $ (ABB'A') $ bằng", "choices": ["$ \\dfrac{\\sqrt{2}}{2} $", "$ \\dfrac{\\sqrt{3}}{3} $", "$ \\dfrac{\\sqrt{3}}{6} $", "$ \\sqrt{2} $"], "correctIndex": 0, "explain": "Ta có $\\heva{&A'C'\\perp A A'\\\\ & A'C'\\perp A'B'}\\Rightarrow A'C'\\perp\\left(A B B'A'\\right)\\Rightarrow A'C'\\perp B A'$.<br>$ BA' $ là hình chiếu vuông góc của $ BC' $ lên $ (ABB'A') \\Rightarrow\\left(B C',\\left(A B B'A'\\right)\\right)=\\left(B C', B A'\\right)=\\widehat{A'B C'}$.<br>Tam giác $ A'BC' $ vuông tại $ A' $, ta có $\\tan \\widehat{A'B C'}=\\dfrac{A' C'}{A'B}=\\dfrac{a}{a \\sqrt{2}}=\\dfrac{\\sqrt{2}}{2}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử, Sở GD và ĐT - Phú Thọ, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tứ diện đều $ABCD$ có cạnh bằng $a$. Gọi $\\varphi$ là góc giữa $AB$ và mặt phẳng $(BCD)$. Tính $\\cos\\varphi$.", "choices": ["$\\dfrac{\\sqrt{3}}{2}$", "$\\dfrac{\\sqrt{2}}{2}$", "$\\dfrac{\\sqrt{3}}{3}$", "$\\dfrac{1}{2}$"], "correctIndex": 2, "explain": "Gọi $M$ là trung điểm của $CD$, $H$ là trọng tâm của tam giác $BCD$.<br>Vì $BCD$ là tam giác đều nên $H$ cũng là tâm đường tròn ngoại tiếp tam giác $BCD$.<br>Suy ra $AH\\perp (BCD)$. Cho nên $HB$ là hình chiếu vuông góc của $AB$ trên $(BCD)$.<br>Vậy góc giữa $AB$ và $(BCD)$ bằng góc giữa $AB$ và $HB$, chính là $\\widehat{ABH}$ $\\Big($vì $\\widehat{AHB}=90^\\circ \\Big)$.<br>Ta có $BM=\\dfrac{a\\sqrt{3}}{2}$, $BH=\\dfrac{2}{3}BM=\\dfrac{a\\sqrt{3}}{3}$.<br>\\noindent  Trong tam giác $ABH$ vuông tại $H$, ta có $\\cos\\varphi=\\cos\\widehat{ABH}=\\dfrac{BH}{AB} = \\dfrac{\\sqrt{3}}{3}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "KSCL cuối năm Sở GD&ĐT Hà Nam, 2020-2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình lăng trụ đứng $A B C D \\cdot A' B' C' D'$ có đáy $A B C D$ là hình thoi, $A B=2$, $ B D=2 \\sqrt{3}$ và $A A'=2 \\sqrt{3}$. Góc giữa đường thẳng $A' C$ và mặt phẳng $ (A B C D)$ bằng", "choices": ["$30^{\\circ}$", "$45^{\\circ}$", "$60^{\\circ}$", "$90^{\\circ}$"], "correctIndex": 2, "explain": "Do $ AA'\\perp(ABCD)$ nên $ (A'C,(ABCD))=\\widehat{ACA'}\\quad(1)$.<br>Gọi $ O $ là giao điểm của $ AC $ và $ BD $. Khi đó, $ O $ là trung điểm của $ AC $ và $ BD $, đồng thời $ \\triangle AOB $ vuông tại $ O $.  {\\allowdisplaybreaks  \\begin{eqnarray*}  OA&=&\\sqrt{AB^2-OB^2}=\\sqrt{AB^2-\\left(\\dfrac{BD}{2}\\right)^2} <br>&=&\\sqrt{2^2-3}=1  \\end{eqnarray*}  }<br>\\noindent $ \\Rightarrow AC=2OA=2\\Rightarrow \\tan\\widehat{ACA'}=\\dfrac{AA'}{AC}=\\dfrac{2\\sqrt{3}}{2}=\\sqrt{3}\\Rightarrow \\widehat{ACA'}=60^{\\circ}.\\quad(2) $<br>Từ $ (1)$ và $ (2)$, ta được $ (A'C,(ABCD))=60^{\\circ} $.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi Thử, Trường THPT Thành Nhân-TP Hồ Chí Minh, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình lăng trụ tam giác đều $ABC.A'B'C'$ có tất cả các cạnh đều bằng $2$. Góc giữa đường thẳng $AC'$ và mặt phẳng đáy bằng bao nhiêu?", "choices": ["$30^\\circ$", "$60^\\circ$", "$45^\\circ$", "$90^\\circ$"], "correctIndex": 2, "explain": "Ta có $CC'\\perp (ABC)$ $\\Rightarrow AC$ là hình chiếu của $AC'$ lên $(ABC)$.<br>Do đó góc giữa $AC'$ và $(ABC)$ là $\\widehat{C'AC}$.<br>Tam giác $CC'A$ vuông cân tại $C$ nên $\\widehat{C'AC}=45^\\circ$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "KSCL, lần 1, Thiệu Hóa - Thanh Hóa, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy $ABCD$ là hình vuông với $AC=5\\sqrt{2}$. Biết $SA$ vuông góc với $(ABCD)$ và $SA=5$. Góc giữa đường thẳng $SD$ và mặt phẳng $(SAB)$ bằng", "choices": ["$30^\\circ$", "$60^\\circ$", "$90^\\circ$", "$45^\\circ$"], "correctIndex": 3, "explain": "Vì $\\heva{&SA\\perp (ABCD)\\Rightarrow SA\\perp AD\\\\&AD\\perp AB}\\Rightarrow AD\\perp (SAB)$ <br>nên $SA$ là hình chiếu vuông góc của $SD$ lên mặt phẳng $(SAB)$.<br>Do đó $\\left(SD, (SAB)\\right)=\\left(SD,SA\\right)=\\widehat{ASD}$.<br>Ta có $AD^2+DC^2=AC^2\\Leftrightarrow 2AD^2=AC^2\\Rightarrow AD=\\dfrac{AC}{\\sqrt{2}}=5$.<br>Xét $\\triangle SAD$ vuông tại $A$ có $\\tan \\widehat{ASD}=\\dfrac{AD}{SA}=1\\Rightarrow \\widehat{ASD}=45^\\circ$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Đề thi KSCL - Sở GDDT - Thanh Hóa, năm 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình lập phương $ABCD.A'B'C'D'$. Gọi $M$, $N$ lần lượt là trung điểm của cạnh $AC$ và $B'C'$. Gọi $\\alpha$ là góc hợp giữa đường thẳng $MN$ và mặt phẳng $\\left(A'B'C'D'\\right)$. Tính giá trị của $\\sin \\alpha$.", "choices": ["$\\dfrac{\\sqrt{5}}{5}$", "$ \\dfrac{2}{\\sqrt{5}}$", "$\\dfrac{\\sqrt{2}}{2}$", "$ \\dfrac{1}{2}$"], "correctIndex": 1, "explain": "Gọi $P$ là trung điểm $BC$, ta có $NP \\perp (ABCD)$. <br>Ta có<br>$\\left(MN;(A'B'C'D')\\right)=\\left(MN;(ABCD)\\right)=\\left(MN;PM\\right) = \\widehat{NMP}$.<br>Gọi độ dài cạnh của hình lập phương là $x$, ta có <br>$NP=x$, $MP=\\dfrac{x}{2}$.<br>Xét $\\triangle MNP$ vuông tại $P$ có $MN =\\sqrt{NP^2+PM^2}= \\dfrac{\\sqrt{5}x}{2}$.<br>$\\Rightarrow \\sin \\alpha = \\sin \\widehat{NMP} = \\dfrac{NP}{NM}=\\dfrac{2}{\\sqrt{5}}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.7, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\coordinate (A) at (0,0);\n\t\t\t\t\t\\coordinate (B) at ($(A)+(-1.5,-2)$);\n\t\t\t\t\t\\coordinate (C) at ($(B)+(4,0)$);\n\t\t\t\t\t\\coordinate (D) at ($(A)+(4,0)$);\n\t\t\t\t\t\\coordinate (A') at ($(A)+(0,4)$);\n\t\t\t\t\t\\coordinate (B') at ($(B)+(0,4)$);\n\t\t\t\t\t\\coordinate (C') at ($(C)+(0,4)$);\n\t\t\t\t\t\\coordinate (D') at ($(D)+(0,4)$);\n\t\t\t\t\t\\coordinate (M) at ($(A)!0.5!(C)$);\n\t\t\t\t\t\\coordinate (N) at ($(B')!0.5!(C')$);\n\t\t\t\t\t\\coordinate (P) at ($(B)!0.5!(C)$);\n\t\t\t\t\t\\foreach \\x in{A,B,C,D,A',B',C',D',M,N,P}{\n\t\t\t\t\t\t\\filldraw (\\x) circle(1pt);\n\t\t\t\t\t}\n\t\t\t\t\t\\draw (A')--(B')--(C')--(D')--(A') (B')--(B) (C')--(C) (D')--(D) (B')--(C')--(D') (B)--(C)--(D) (N)--(P);\n\t\t\t\t\t\\draw[dashed] (B)--(A)--(A') (A)--(D) (M)--(N) (P)--(M) (A)--(C);\n\t\t\t\t\t\\path\n\t\t\t\t\tnode at (A)[left]{$A$}\n\t\t\t\t\tnode at (B)[below left]{$B$}\n\t\t\t\t\tnode at (C)[below right]{$C$}\n\t\t\t\t\tnode at (D)[right]{$D$}\n\t\t\t\t\tnode at (A')[above]{$A'$}\n\t\t\t\t\tnode at (B')[left]{$B'$}\n\t\t\t\t\tnode at (C')[below right]{$C'$}\n\t\t\t\t\tnode at (D')[right]{$D'$}\n\t\t\t\t\tnode at (M)[above right]{$M$}\n\t\t\t\t\tnode at (N)[above]{$N$}\n\t\t\t\t\tnode at (P)[below]{$P$};\n\t\t\t\t\\end{tikzpicture}</script></div>", "nguon": "KSCL lần 1, Sở GD và ĐT-Thanh Hóa, THPT Triệu Sơn 3, 2020-2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Chóp tam giác đều $S.ABC$ có cạnh đáy bằng $a$, cạnh bên bằng $\\dfrac{2a}{3}$. Góc giữa cạnh bên và mặt đáy bằng", "choices": ["$90^\\circ$", "$45^\\circ$", "$30^\\circ$", "$60^\\circ$"], "correctIndex": 2, "explain": "Gọi $M$ là trung điểm của $BC$, ta có $\\heva{&SM\\perp BC\\\\&AM\\perp BC}\\Rightarrow BC\\perp (SAM)$<br>$\\Rightarrow AM$ là hình chiếu vuông góc của $SA$ lên $(ABC)$.<br>Suy ra góc giữa $SA$ và $(ABC)$ là $\\alpha=\\widehat{\\left(SA,AM\\right)}$, <br>$AM=\\dfrac{\\sqrt{3}a}{2}$, $SM=\\sqrt{SB^2-BM^2}=\\sqrt{\\dfrac{4a^2}{9}-\\dfrac{a^2}{4}}=\\dfrac{\\sqrt{7}}{6}a$<br>Ta có $\\cos\\alpha=\\left|\\cos\\widehat{SAM}\\right|=\\dfrac{\\left|SA^2+AM^2-SM^2\\right|}{2SA\\cdot SM}=\\dfrac{\\left|\\dfrac{4}{9}a^2+\\dfrac{3}{4}a^2-\\dfrac{7}{36}a^2\\right|}{2\\cdot \\dfrac{2a}{3}\\cdot\\dfrac{3}{4}a}=\\dfrac{\\sqrt{3}}{2}$.<br>Suy ra $\\alpha =30^\\circ$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Đề thi thử TN THPT 2021, Chuyên Hạ Long, lần 2"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Chóp tứ giác đều $S.ABCD$ có $AB=a$, $SA=2a$. Tính $\\sin$ của góc giữa đường thẳng $SB$ và $(SAC)$.", "choices": ["$\\dfrac{1}{\\sqrt{7}}$", "$\\dfrac{\\sqrt{14}}{4}$", "$\\dfrac{\\sqrt{2}}{4}$", "$\\dfrac{\\sqrt{2}}{2}$"], "correctIndex": 2, "explain": "Gọi $O$ là giao điểm của $AC$ và $BD$. Ta có $BO\\perp AC$ và $BO\\perp SO$ nên $BO\\perp (SAC)$. Do đó góc giữa $SB$ và $(SAC)$ là góc $\\widehat{BSO}$.<br>Vì $ABCD$ là hình vuông cạnh $a$ nên $BO=\\dfrac{BD}{2}=\\dfrac{a\\sqrt{2}}{2}$, $SB=SA=2a$. Suy ra $\\sin \\widehat{BSO}=\\dfrac{OB}{SB}=\\dfrac{a\\sqrt{2}}{2}:2a=\\dfrac{\\sqrt{2}}{4}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "TT THPT Hòa Vang Đà Nẵng năm 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy $ABCD$ là hình vuông cạnh $a$, $SA$ vuông góc với mặt đáy và $SA=a\\sqrt{3}$ . Gọi $\\alpha$ là góc giữa $SD$ và $(SAC)$. Giá trị của $\\sin \\alpha$ bằng", "choices": ["$\\dfrac{\\sqrt{3}}{4}$", "$\\dfrac{\\sqrt{2}}{4}$", "$\\dfrac{\\sqrt{2}}{3}$", "$\\dfrac{\\sqrt{2}}{2}$"], "correctIndex": 1, "explain": "Gọi $O$ là tâm của hình vuông $ABCD$.<br>Ta có $\\heva{& BD \\perp AC\\\\& BD \\perp SA}\\Rightarrow BD \\perp (SAC)$ tại $O$.<br>Suy ra $SO$ là hình chiếu của $SD$ trên $(SAC)$.<br>Do đó $\\alpha = \\left(SD,(SAC)\\right)=(SD,SO)=\\widehat{DSO}$.<br>Xét $\\triangle SDO$ vuông tại $O$ có<br>a) $OD=\\dfrac{1}{2}BD=\\dfrac{a\\sqrt{2}}{2}$;  <br>b) $SD=\\sqrt{SA^2+AD^2}=\\sqrt{(a\\sqrt{3})^2+a^2}=2a$.<br>Suy ra $\\sin \\alpha=\\dfrac{OD}{SD}=\\dfrac{\\dfrac{a\\sqrt{2}}{2}}{2a}=\\dfrac{\\sqrt{2}}{4}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Đề TT L3, THPT Chuyên Lam Sơn, Sở Thanh Hóa, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S. ABCD$ có đáy $ABCD$ là hình thoi cạnh $a$; $\\widehat{ABC} = 60 ^ \\circ$ và $AB = a$. Hình chiếu vuông góc của điểm $S$ lên mặt phẳng $\\left(ABC \\right) $ trùng với trọng tâm $\\triangle ABC$. Gọi $\\varphi$ là góc giữa đường $SB$ và mặt $(SCD)$. Tính $\\sin \\varphi$.", "choices": ["$\\dfrac{\\sqrt{3}}{2}$", "$\\dfrac{1}{4}$", "$ \\dfrac{1}{2}$", "$\\dfrac{\\sqrt{2}}{2}$"], "correctIndex": 3, "explain": "\\hspace{0.5 cm}<br>Vì $\\heva{&AB = AC = a \\\\&\\widehat{ABC} = 60 ^ \\circ}$ nên $\\triangle ABC$ là tam giác đều cạnh $a$.<br>Gọi $G$ là trọng tâm tam giác $ABC$ $\\Rightarrow SG \\perp \\left( ABCD\\right) $.<br>Gọi $E$ là hình chiếu của $B$ trên $\\left(SCD \\right) $ nên $SE$ là hình chiếu của $SB$ trên mặt phẳng $\\left(SCD \\right)$.<br>Do đó, góc giữa $SB$ và mặt phẳng $\\left(SCD \\right)$ là góc giữa hai đường thẳng $SB$, $SE$ hay $\\widehat{BSE} = \\varphi$.<br>Ta có $BE = {d}\\left(B,(SCD)\\right) $.<br>Vì $BG \\cap (SCD) = D$ nên $$\\dfrac{{d}\\left(B,(SCD) \\right) }{{d}\\left(G,(SCD) \\right)} = \\dfrac{BG}{GC} = \\dfrac{3}{2} \\Rightarrow {d}\\left(B,(SCD) \\right) = \\dfrac{3}{2} {d}\\left(G,(SCD) \\right).$$  Kẻ $GH \\perp SC$ tại $H$. $\\qquad (1)$<br>Ta có $\\heva{&CD \\perp CG\\\\&CD \\perp SG} \\Rightarrow CD \\perp (SCG) \\Rightarrow CD \\perp HG. \\qquad (2)$<br>Từ $(1)$ và $(2)$ suy ra $GH \\perp (SCD)$ hay ${d} \\left(G, (SCD) \\right) = GH $.<br>Vì $G$ là trọng tâm tam giác $ABC$ nên $CG = \\dfrac{2}{3} \\cdot \\dfrac{a \\sqrt{3}}{2} = \\dfrac{a}{\\sqrt{3}}$.<br>Xét tam giác $SBG$ vuông tại $G$ có $SG = \\sqrt{SB^2 - AG^2} = \\sqrt{a^2 - \\dfrac{a^2}{3}} = \\dfrac{a \\sqrt{6}}{3}$.<br>Xét tam giác $SCG$ vuông tại $G$, ta có  \\[\\dfrac{1}{HG^2} = \\dfrac{1}{GS^2}+ \\dfrac{1}{GC^2} = \\dfrac{9}{6a^2}+ \\dfrac{3}{a^2} = \\dfrac{9}{2a^2} \\Rightarrow HG = \\dfrac{a \\sqrt{2}}{3} \\Rightarrow BE = \\dfrac{3}{2}HG= \\dfrac{a \\sqrt{2}}{2}.\\]  Xét tam giác $SEB$ vuông tại $E$, ta có $\\sin \\varphi = \\dfrac{BE}{SB}= \\dfrac{\\dfrac{a\\sqrt{2}}{2}}{a} = \\dfrac{\\sqrt{2}}{2}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.8, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\path\n\t\t\t\t\t(0,0) coordinate (G)\n\t\t\t\t\t(0,4) coordinate (S)\n\t\t\t\t\t(-3,-1) coordinate (A)\n\t\t\t\t\t(2,-1) coordinate (D)\n\t\t\t\t\t($(D)!3/2!(G)$) coordinate (B)\n\t\t\t\t\t($(B)+(D)-(A)$) coordinate (C)\n\t\t\t\t\t($(S)!0.4!(C)$) coordinate (H)\n\t\t\t\t\t;\n\t\t\t\t\t\\draw (S)--(A)--(D)--(C)--(S)--(D);\n\t\t\t\t\t\\draw[dashed] (D)--(B)--(S)--(G)--(H) (A)--(B)--(C)--(A) (G)--(C);\n\t\t\t\t\t\\foreach \\x/\\g in\n\t\t\t\t\t{A/-90,B/180,C/0,D/-90,S/180,G/200,H/40}\n\t\t\t\t\t\\fill[black](\\x) circle (1.2pt)\n\t\t\t\t\t($(\\x)+(\\g:3mm)$) node{$\\x$};\n\t\t\t\t\\end{tikzpicture}</script></div>", "nguon": "KSCL lần 1 -Lê Quý Đôn - Hải Phòng, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình chóp $S.ABC$ có đáy $ABC$ là tam giác vuông tại $A$, $\\widehat{ABC}={60}^{\\circ}$, tam giác $SBC$ là tam giác đều có bằng cạnh $2a$ và nằm trong mặt phẳng vuông với đáy. Gọi $\\varphi $ là góc giữa hai mặt phẳng $\\left(SAC\\right)$ và $\\left(ABC\\right)$. Mệnh đề nào sau đây đúng?", "choices": ["$\\tan \\varphi =\\dfrac{\\sqrt{3}}{6}$", "$\\tan \\varphi =\\dfrac{1}{2}$", "$\\varphi =60^\\circ$", "$\\tan \\varphi =2\\sqrt{3}$"], "correctIndex": 3, "explain": "Gọi $H$ là trung điểm của $BC$, suy ra $SH\\perp BC\\Rightarrow SH\\perp \\left(ABC\\right)$.<br>Gọi $K$ là trung điểm $AC$, suy ra $HK\\parallel AB$ nên $HK\\perp AC$.<br>Ta có $\\heva{& AC\\perp HK \\\\ & AC\\perp SH \\\\}\\Rightarrow AC\\perp \\left(SHK\\right)\\Rightarrow AC\\perp SK.$<br>Do đó $\\left(\\left(SAC\\right),\\left(ABC\\right)\\right)=\\left(SK,HK\\right)=\\widehat{SKH}.$<br>Tam giác vuông $ABC$, có $AB=BC\\cdot \\cos \\widehat{ABC}=a\\Rightarrow HK=\\dfrac{1}{2}AB=\\dfrac{a}{2}.$<br>Tam giác vuông $SHK$, có $\\tan \\widehat{SKH}=\\dfrac{SH}{HK}=2\\sqrt{3}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác đều $ABC$ cạnh $a$. Gọi $D$ là điểm đối xứng với $A$ qua $BC$. Trên đường thẳng vuông góc với mặt phẳng $\\left(ABC\\right)$ tại $D$ lấy điểm $S$ sao cho $SD=\\dfrac{a\\sqrt{6}}{2}$. Gọi $I$ là trung điểm $BC$, kẻ $IH$ vuông góc $SA\\left(H\\in SA\\right)$. Khẳng định nào sau đây <b>sai</b>?", "choices": ["$\\left(SDB\\right)\\perp \\left(SDC\\right)$", "$\\left(SAB\\right)\\perp \\left(SAC\\right)$", "$BH\\perp HC$", "$SA\\perp BH$"], "correctIndex": 0, "explain": "Từ giả thiết suy ra $ABDC$ là hình thoi nên $BC\\perp AD.$<br>Ta có $\\heva{& BC\\perp AD \\\\ & BC\\perp SD \\\\}\\Rightarrow BC\\perp \\left(SAD\\right)\\Rightarrow BC\\perp SA$.<br>Lại có theo giả thiết $IH\\perp SA$. Từ đó suy ra $SA\\perp \\left(HCB\\right)$ $\\Rightarrow SA\\perp BH$.<br>Tính được: $AI=\\dfrac{a\\sqrt{3}}{2}$, $AD=2AI=a\\sqrt{3}$ và $SA=\\sqrt{AD^2+SD^2}=\\dfrac{3a\\sqrt{2}}{2}.$<br>Ta có $\\triangle AHI\\backsim \\triangle ADS\\Rightarrow \\dfrac{IH}{SD}=\\dfrac{AI}{AS}\\Rightarrow IH=\\dfrac{AI\\cdot SD}{AS}=\\dfrac{a}{2}=\\dfrac{BC}{2}\\Rightarrow $ tam giác $HBC$ có trung tuyến $IH$ bằng nửa cạnh đáy $BC$ nên $\\widehat{BHC}=90^0$ hay $BH\\perp HC$.<br>\\noindent Từ đó suy ra $\\left(SAB\\right)\\perp \\left(SAC\\right)$.<br>Dùng phương pháp loại trừ thì khẳng định “$\\left(SDB\\right)\\perp \\left(SDC\\right)$” là <b>sai</b>.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Chóp $S.ABC$ có đáy $ABC$ là tam giác vuông cân tại $C$. Gọi $H$ là trung điểm $AB$. Biết rằng $SH$ vuông góc với mặt phẳng $\\left(ABC\\right)$ và $AB=SH=a.$ Tính cosin của góc $\\alpha $ là góc giữa $\\left(SAB\\right)$ và $\\left(SAC\\right)$.", "choices": ["$\\dfrac{\\sqrt{2}}{3}$", "$\\dfrac{\\sqrt{3}}{3}$", "$\\dfrac{2}{3}$", "$\\dfrac{1}{3}$"], "correctIndex": 2, "explain": "Ta có $SH\\perp \\left(ABC\\right)\\Rightarrow SH\\perp CH$. \\hfill $(1)$ <br>Tam giác $ABC$ cân tại $C$ nên $CH\\perp AB$.\\hfill $(2)$ <br>Từ $(1)$ và $(2)$, suy ra $CH\\perp \\left(SAB\\right)$.<br>Gọi $I$ là trung điểm $AC$ $\\Rightarrow HI\\parallel BC\\Rightarrow HI\\perp AC$.\\hfill $(3)$<br>Mặt khác $AC\\perp SH$ (do $SH\\perp \\left(ABC\\right)$).\\hfill $(4)$<br>Từ $(3)$ và $(4)$, suy ra $AC\\perp \\left(SHI\\right)$. <br>Kẻ $HK\\perp SI \\left(K\\in SI\\right)$.\\hfill $(5)$<br>Từ $AC\\perp \\left(SHI\\right)\\Rightarrow AC\\perp HK$.\\hfill$(6)$<br>Từ $(5)$ và $(6)$, suy ra $HK\\perp \\left(SAC\\right)$. <br>Vì $\\heva{& HK\\perp \\left(SAC\\right) \\\\ & HC\\perp \\left(SAB\\right) \\\\}$ nên góc giữa hai mặt phẳng $\\left(SAC\\right)$ và $\\left(SAB\\right)$ bằng góc giữa hai đường thẳng $HK$ và $HC$.<br>\\noindent Xét tam giác $CHK$ vuông tại $K$, có $CH=\\dfrac{1}{2}AB=\\dfrac{a}{2}$; $\\dfrac{1}{HK^2}=\\dfrac{1}{SH^2}+\\dfrac{1}{HI^2}\\Rightarrow HK=\\dfrac{a}{3}$.<br>Do đó $\\cos \\widehat{CHK}=\\dfrac{HK}{CH}=\\dfrac{2}{3}.$<br>\\begin{nx}  Bài làm sử dụng lý thuyết “$\\heva{& d_1\\perp \\left(\\alpha \\right) \\\\ & d_2\\perp \\left(\\beta \\right)}\\Rightarrow \\left(\\left(\\alpha \\right),\\left(\\beta \\right)\\right)=(d_1,d_2)$”. <br>Nếu ta sử dụng lý thuyết quen thuộc “góc giữa hai mặt phẳng bằng góc giữa hai đường thẳng lần lượt nằm trong hai mặt phẳng và cùng vuông góc với giao tuyến” thì rất khó.  \\end{nx}<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trong không gian cho tam giác đều $SAB$ và hình vuông $ABCD$ cạnh $a$ nằm trên hai mặt phẳng vuông góc. Gọi $H,K$ lần lượt là trung điểm của $AB$, $CD$. Gọi $\\varphi $ là góc giữa hai mặt phẳng $\\left(SAB\\right)$ và $\\left(SCD\\right)$. Mệnh đề nào sau đây đúng?", "choices": ["$\\tan \\varphi =\\dfrac{2\\sqrt{3}}{3}$", "$\\tan \\varphi =\\dfrac{\\sqrt{3}}{3}$", "$\\tan \\varphi =\\dfrac{\\sqrt{3}}{2}$", "$\\tan \\varphi =\\dfrac{\\sqrt{2}}{3}$"], "correctIndex": 0, "explain": "Dễ dàng xác định giao tuyến của hai mặt phẳng $\\left(SAB\\right)$ và $\\left(SCD\\right)$ là đường thẳng $d$ đi qua $S$ và song song với $AB$.<br>Trong mặt phẳng $\\left(SAB\\right)$ có $SH\\perp AB\\Rightarrow SH\\perp d.$<br>Ta có $$\\heva{& CD\\perp HK <br>& CD\\perp SH <br>}\\Rightarrow CD\\perp \\left(SHK\\right)\\Rightarrow CD\\perp SK\\Rightarrow d\\perp SK.$$  Từ đó suy ra $\\left(\\left(SAB\\right),\\left(SCD\\right)\\right)=(SH,SK)=\\widehat{HSK}.$<br>Trong tam giác vuông $SHK$, có $\\tan \\widehat{HSK}=\\dfrac{HK}{SH}=\\dfrac{2\\sqrt{3}}{3}.$<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình chóp $S.ABC$ có đáy $ABC$ là tam giác vuông tại $B,$ cạnh bên $SA$ vuông góc với đáy. Gọi $E,F$ lần lượt là trung điểm của các cạnh $AB$ và $AC.$ Góc giữa hai mặt phẳng $\\left(SEF\\right)$ và $\\left(SBC\\right)$ là", "choices": ["$\\widehat{BSE}$", "$\\widehat{CSF}$", "$\\widehat{BSF}$", "$\\widehat{CSE}$"], "correctIndex": 0, "explain": "Gọi $d$ là đường thẳng đi qua $S$ và song song với $EF.$<br>Vì $EF$ là đường trung bình tam giác $ABC$ suy ra $EF\\parallel BC$.<br>Khi đó $d\\parallel EF \\parallel BC$$\\Rightarrow $$\\left(SEF\\right)\\cap \\left(SBC\\right)=d$.\\hfill $(1)$ <br>Ta có $\\heva{& SA\\perp BC \\\\ & AB\\perp BC \\\\}$ suy ra $BC\\perp \\left(SAB\\right)\\Rightarrow \\heva{& BC\\perp SE \\\\ & BC\\perp SB}$.\\hfill $(2)$<br>Từ $(1), (2)$ suy ra $\\heva{& d\\perp SE \\\\ & d\\perp SB}$.<br>Dẫn tới $\\left(\\left(SEF\\right);\\left(SBC\\right)\\right)=\\left(SE;SB\\right)=\\widehat{BSE}.$<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình chóp $S.ABC$ có đáy $ABC$ là tam giác vuông tại $C$, mặt bên $SAC$ là tam giác đều và mằm trong mặt phẳng vuông góc với đáy. Gọi $I$ là trung điểm của $SC$. Mệnh đề nào sau đây <b>sai</b>?", "choices": ["$AI\\perp SC$", "$\\left(ABI\\right)\\perp \\left(SBC\\right)$", "$\\left(SBC\\right)\\perp \\left(SAC\\right)$", "$AI\\perp BC$"], "correctIndex": 2, "explain": "Tam giác $SAC$ đều có $I$ là trung điểm của $SC$ nên $AI\\perp SC$.<br>Gọi $H$ là trung điểm $AC$ suy ra $SH\\perp AC$.<br>Mà $\\left(SAC\\right)\\perp \\left(ABC\\right)$ theo giao tuyến $AC$ nên $SH\\perp \\left(ABC\\right)$ do đó $SH\\perp BC$.<br>Hơn nữa theo giả thiết tam giác $ABC$ vuông tại $C$ nên $BC\\perp AC$. <br>Từ đó suy ra $BC\\perp \\left(SAC\\right)\\Rightarrow BC\\perp AI$.<br>Từ đó suy ra $\\left(ABI\\right)\\perp \\left(SBC\\right)$.<br>Dùng phương pháp loại trừ thì khẳng định “$\\left(SBC\\right)\\perp \\left(SAC\\right)$” là <b>sai</b>.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABC$ có đáy là tam giác vuông đỉnh $A$, $AC=a$, $SC$ vuông góc với mặt phẳng đáy và $SC=a$. Khoảng cách từ $C$ đến mặt phẳng $(SAB)$ bằng", "choices": ["$\\dfrac{a\\sqrt{2}}{2}$", "$a$", "$\\dfrac{a\\sqrt{6}}{3}$", "$\\dfrac{a}{2}$"], "correctIndex": 0, "explain": "Kẻ $CH\\perp SA$.<br>Từ $\\heva{& AB\\perp AC \\\\ & AB\\perp SC}\\Rightarrow AB\\perp (SAC)\\Rightarrow AB\\perp CH$.<br>Từ $\\heva{& CH\\perp SA \\\\ & CH\\perp AB}\\Rightarrow CH\\perp (SAB)\\Rightarrow CH={d}(C,(SAB))$.<br>Áp dụng hệ thức lượng cho $\\triangle SCA$ (vuông tại $C$) có  \\begin{align*}  \\dfrac{1}{CH^2}=\\dfrac{1}{CS^2}+\\dfrac{1}{CA^2}=\\dfrac{1}{a^2}+\\dfrac{1}{a^2}=\\dfrac{2}{a^2}\\Rightarrow CH=\\dfrac{a\\sqrt{2}}{2}.  \\end{align*}  Suy ra ${d}(C,(SAB))=\\dfrac{a\\sqrt{2}}{2}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử, Sở GD và ĐT - Tiền Giang, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABC$ có đáy $ABC$ là tam giác đều và $SA\\perp (ABC)$, $AB=a$. Khoảng cách từ $C$ đến $(SAB)$ bằng", "choices": ["$\\dfrac{a}{2}$", "$a$", "$\\dfrac{a\\sqrt{3}}{2}$", "$\\dfrac{a\\sqrt{2}}{2}$"], "correctIndex": 2, "explain": "Kẻ $CM\\perp AB$, vì $SA\\perp (ABC)$ nên $CM\\perp (SAB)$.<br>Do đó ${d}(C,(SAB))=CM$.<br>Lại có $\\triangle ABC$ đều cạnh $a$ nên $CM=\\dfrac{a\\sqrt{3}}{2}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "TT THPT Hòa Vang Đà Nẵng năm 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.A B C D$ có đáy là hình vuông và $S A=a$, $S B=a\\sqrt{3}$. $\\triangle S A B$ vuông tại $S$ và nằm trong mặt phẳng vuông góc với đáy. Tính khoảng cách từ $B$ đến $(S A D)$.", "choices": ["$a\\sqrt{2}$", "$ \\dfrac{a\\sqrt{3}}{2}$", "$ \\dfrac{a\\sqrt{2}}{2}$", "$a\\sqrt{3}$"], "correctIndex": 3, "explain": "Ta có $AD\\perp AB$. Vì $(SAB)\\perp (ABCD)$ nên $AD\\perp (SAB)$. Suy ra $AD\\perp SB$.<br>Mặt khác $\\triangle SAB$ vuông tại $S$ nên $SB\\perp SA$.<br>Khi đó $SB\\perp (SAD)$.  <br>Vậy ${d}[B,(SAD)]=SB=a\\sqrt{3}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử, Việt Yên số 1 - Bắc Giang, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy là hình thoi cạnh $a$, $\\widehat{BAD}=60^{\\circ}$, cạnh bên $SA=a$ và $SA$ vuông góc với mặt phẳng đáy. Tính khoảng cách từ $B$ đến $(SCD)$.", "choices": ["$\\dfrac{a\\sqrt{21}}{7}$", "$\\dfrac{a\\sqrt{15}}{7}$", "$\\dfrac{a\\sqrt{21}}{3}$", "$\\dfrac{a\\sqrt{15}}{3}$"], "correctIndex": 0, "explain": "Ta có<br>$BA\\parallel DC\\subset(SDC)\\Rightarrow BA\\parallel (SDC)$<br>$\\Rightarrow {d}(B,(SDC))={d}(A,(SDC))$.<br>Kẻ $AH\\perp CD$ tại $H$, có<br>$\\heva{&SA\\perp CD\\\\&AH\\perp CD}\\Rightarrow CD\\perp(SAH)$<br>$\\Rightarrow(SCD)\\perp(SAH);(SCD)\\cap(SAH)=SH$. <br>Kẻ $AK\\perp SH\\Rightarrow AK\\perp(SCD)\\Rightarrow {d}(A,(SDC))=AK$.  \\noindent   Có $ABCD$ là hình thoi cạnh $a$, $\\widehat{BAD}=60^{\\circ}$ nên $\\widehat{HDA}=60^{\\circ}$.<br>Trong tam giác $AHD$ vuông tại $H$, $AH=\\sin\\widehat{HDA}\\cdot AD=\\dfrac{\\sqrt{3}a}{2}$.<br>Trong tam giác $AHS$ vuông tại $A$, có   $\\dfrac{1}{AK^2}=\\dfrac{1}{AS^2}+\\dfrac{1}{AH^2}=\\dfrac{7}{3a^2}\\Rightarrow AK=\\dfrac{a\\sqrt{21}}{7}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round,>=stealth]\n\t\t\t\t\t\\path\n\t\t\t\t\t(0,0) coordinate (A)\n\t\t\t\t\t(-1.3,-1.6) coordinate (B)\n\t\t\t\t\t(2.5,-1.6)coordinate (C)\n\t\t\t\t\t($(A)+(C)-(B)$) coordinate (D)\n\t\t\t\t\t($(A)+(0,3)$) coordinate (S)\n\t\t\t\t\t($(C)!1.5!(D)$) coordinate (H)\n\t\t\t\t\t($(S)!0.6!(H)$) coordinate (K)\n\t\t\t\t\t;\n\t\t\t\t\t\\draw (S)--(B)--(C)--(D)--cycle (D)--(H)--(S)--(C);\n\t\t\t\t\t\\draw[dashed] (S)--(A)--(D) (H)--(A)--(B) (A)--(K);\t\n\t\t\t\t\t\\foreach \\p/\\q in {S/90,A/-90,B/-90,C/-90,D/-10,H/-20,K/40}\t\t\t\n\t\t\t\t\t\\fill[black] (\\p) circle (1.0pt)node[shift={(\\q:2.5mm)}]{$\\p$};\n\t\t\t\t\\end{tikzpicture}</script></div>", "nguon": "Thi thử Trực tuyến Lần 4, Sở GD và ĐT - Hà Tĩnh, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho lăng trụ đứng $ABC.A'B'C'$ có độ dài cạnh bên bằng $3 $, đáy $ABC$ là tam giác vuông tại $B$ và $AB=2$. Khoảng cách từ $A$ đến mặt phẳng $\\left(A'BC\\right)$ bằng", "choices": ["$\\dfrac{13}{36}$", "$\\dfrac{6 \\sqrt{13}}{13}$", "$\\dfrac{\\sqrt{13}}{13}$", "$\\dfrac{6}{13}$"], "correctIndex": 1, "explain": "Kẻ $AH\\perp A'B$. Ta có  \\[\\heva{&BC\\perp AB\\\\&BC\\perp AA'} \\Rightarrow BC\\perp (AA'B)\\Rightarrow BC\\perp AH.\\]  Ta có  \\[\\heva{&AH\\perp BC\\\\&AH\\perp A'B}\\Rightarrow AH\\perp (A'BC).\\]  Suy ra khoảng cách từ $A$ đến mặt phẳng $\\left(A'BC\\right)$ là ${\\,d} =AH$.<br>\\noindent   Theo hệ thức lượng trong tam giác vuông, ta có   \\allowdisplaybreaks  \\begin{eqnarray*}  &&\\dfrac{1}{AH^2}=\\dfrac{1}{AB^2}+\\dfrac{1}{AA'^2}=\\dfrac{1}{4}+\\dfrac{1}{9}=\\dfrac{13}{36}<br>&\\Rightarrow & AH=\\dfrac{6\\sqrt{13}}{13}.  \\end{eqnarray*}  Vậy khoảng cách từ $A$ đến mặt phẳng $\\left(A'BC\\right)$ là $\\dfrac{6\\sqrt{13}}{13}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử lần 4, THPT Triệu Sơn 3, Thanh Hóa, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy $ABCD$ là hình vuông cạnh $a$. Mặt bên $SAB$ là tam giác đều và nằm trong mặt phẳng vuông góc với đáy. Tính khoảng cách từ trung điểm $I$ của $AB$ đến $(S CD)$?", "choices": ["$\\dfrac{a \\sqrt{5}}{5}$", "$\\dfrac{a \\sqrt{21}}{7}$", "$\\dfrac{a}{2}$", "$\\dfrac{a \\sqrt{3}}{2}$"], "correctIndex": 1, "explain": "Theo bài ra $SI$ là đường cao của hình chóp.<br>Gọi $K$ là trung điểm của $CD$, kẻ $IH\\perp SK$ tại $K$.<br>Ta có $\\heva{&CD\\perp IK\\\\&CD\\perp SI}\\Rightarrow CD\\perp (SIK)\\Rightarrow CD\\perp IH$.<br>Có $\\heva{&IH\\perp SK\\\\&IH\\perp CD}\\Rightarrow IH\\perp (SCD)$.<br>Vậy ${d}(I,(SCD))=IH$.<br>\\noindent  Có $SI=\\dfrac{a\\sqrt{3}}{2}$, $IK=a$.<br>Xét $\\triangle SIK$ có $\\dfrac{1}{IH^2}=\\dfrac{1}{IS^2}+\\dfrac{1}{IK^2}=\\dfrac{4}{3a^2}+\\dfrac{1}{a^2}=\\dfrac{7}{3a^2}\\Rightarrow IH=\\dfrac{a\\sqrt{21}}{7}$.<br>Vậy ${d}(I,(SCD))=\\dfrac{a\\sqrt{21}}{7}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử Lần 3, THPT Nguyễn Đăng Đạo, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy $ABCD$ là hình thoi cạnh bằng   $a$, $\\widehat{BAD} = 120^{\\circ}$. Mặt bên $SAB$ là tam giác đều và $(SAB)\\perp(ABCD)$. Tính khoảng cách từ $A$ đến $(SBC)$.", "choices": ["$\\dfrac{a\\sqrt{7}}{7}$", "$\\dfrac{a\\sqrt{3}}{4}$", "$\\dfrac{a\\sqrt{15}}{5}$", "$\\dfrac{a}{2}$"], "correctIndex": 2, "explain": "Ta có $\\heva{&(SAB)\\perp(ABCD)\\\\&(SAB)\\cap(ABCD)=AB\\\\& SH \\subset (SAB)\\\\&SH\\perp AB} \\Rightarrow SH \\perp (ABCD)$.<br>Qua $H$ kẻ $HK \\perp BC$ tại $K$, khi đó ta có   \\[\\heva{& SH \\perp BC\\\\& HK \\perp BC} \\Rightarrow BC \\perp (SHK).\\]  Qua $H$ dựng $HI \\perp  SK, (I \\in SK)$, khi đó  \\[\\heva{ & HI\\perp BC \\\\ & HI \\perp SK} \\Rightarrow HI\\perp (SBC) \\Rightarrow {d}\\left(H, (SBC)\\right)=HI.\\]<br>\\noindent Ta có $AH\\cap(SBC)=B \\Rightarrow \\dfrac{{d}\\left(A, (SBC)\\right)}{{d}\\left(H, (SBC)\\right)}=\\dfrac{BA}{BH}=2$. <br>Suy ra ${d}\\left(A, (SBC)\\right) = 2{d}\\left(H, (SBC)\\right)=2HI$. <br>Ta có $SH = \\dfrac{a\\sqrt{3}}{2}$, $HK = \\sin\\widehat{HBK} \\cdot BH= \\dfrac{a\\sqrt{3}}{4}$.<br>Xét tam giác $SHK$ vuông tại $H$ ta có  \\[\\dfrac{1}{HI^2}=\\dfrac{1}{SH^2}+\\dfrac{1}{HK^2} \\Leftrightarrow HI=\\dfrac{SH\\cdot HK}{\\sqrt{SH^2 +HK^2}}=\\dfrac{a\\sqrt{15}}{10}.\\]  Vậy $ {d}\\left(A, (SBC)\\right) = 2HI=\\dfrac{a\\sqrt{15}}{5}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử L2, Sở Vĩnh Phúc, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp đều $S.ABCD$ có đáy $ABCD$ là hình vuông tâm $O$ cạnh $a$, cạnh bên tạo với đáy một góc $60^\\circ$. Gọi $M$ là điểm thuộc cạnh $SB$ sao cho $SM=\\dfrac{2}{3}SB$ . Tính khoảng cách từ $M$ đến mặt phẳng $(SCD)$.", "choices": ["$\\dfrac{2a\\sqrt{42}}{21}$", "$\\dfrac{a\\sqrt{42}}{14}$", "$\\dfrac{a\\sqrt{42}}{21}$", "$\\dfrac{a\\sqrt{42}}{7}$"], "correctIndex": 0, "explain": "Hình chóp $S.ABCD$ đều và $O$ là tâm hình vuông $ABCD$ nên suy ra $SO\\perp (ABCD)$.<br>Góc giữa cạnh bên với đáy của hình chóp bằng $60^\\circ$ nên suy ra $\\widehat{SAO}=60^\\circ$.<br>Ta có $SO= OA\\cdot \\tan SAO =\\dfrac{a\\sqrt{2}}{2}\\cdot \\tan 60^\\circ =\\dfrac{a\\sqrt{6}}{2}$.<br>Gọi $N$ là trung điểm $CD$, khi đó $CD\\perp (SON)$.<br>Kẻ $OH\\perp SN$ tại $H$. Từ $CD\\perp (SON)\\Rightarrow OH\\perp CD$.<br>Do đó $OH\\perp (SCD)$, nên $OH={d}\\left[O,(SCD)\\right]$.  \\noindent  Xét tam giác $SON$ vuông tại $O$, ta có  \\[OH=\\dfrac{SO\\cdot ON}{\\sqrt{SO^2+ON^2}}=\\dfrac{\\dfrac{a\\sqrt{6}}{2}\\cdot \\dfrac{a}{2}}{\\sqrt{\\left(\\dfrac{a\\sqrt{6}}{2}\\right)^2+\\left(\\dfrac{a}{2}\\right)^2}}=\\dfrac{a\\sqrt{42}}{14}.\\]  Vì $\\dfrac{MS}{BA}=\\dfrac{2}{3}$ và $\\dfrac{BD}{OD}=2$ nên  \\[{d}\\left[M,(SCD)\\right]=\\dfrac{2}{3}{d}\\left[B,(SCD)\\right]=\\dfrac{4}{3}{d}\\left[O,(SCD)\\right]=\\dfrac{4}{3}\\cdot \\dfrac{a\\sqrt{42}}{14}=\\dfrac{2a\\sqrt{42}}{21}.\\]<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Đề GHK2 THPT Nguyễn Trung Thiên - Hà Tĩnh - 21"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy là hình thang vuông tại $A$, $B$. Biết $AB=BC=a$, $AD=2a$. Hình chiếu vuông góc của $S$ lên mặt phẳng đáy trùng với trung điểm $H$ của $AD$ và $SH=\\dfrac{a\\sqrt{6}}{2}$. Tính khoảng cách từ $B$ đến $(SCD)$.", "choices": ["$\\dfrac{3a}{4}$", "$\\dfrac{a\\sqrt{6}}{4}$", "$\\dfrac{3a\\sqrt{6}}{4}$", "$\\dfrac{a\\sqrt{6}}{8}$"], "correctIndex": 1, "explain": "Xét tứ giác $BCDH$ có $BC \\parallel HD$ và $BC=HD=\\dfrac{1}{2}AD=a$ nên $BCDH$ là hình bình hành, suy ra $BH \\parallel (SCD)$.<br>Do đó ${d}\\left(B,(SCD)\\right)={d}\\left(H,(SCD)\\right)$.<br>Dựng $\\heva{& HE\\perp CD ~\\text{tại}~E & (1)\\\\ & HF \\perp SE~\\text{tại}~F. & (2)}$<br>Ta có $SH\\perp  CD~\\left(\\text{ do }~SH \\perp (ABCD) \\supset CD\\right)$. \\quad $(3)$<br>Từ $(1)$, $(3)$ $\\Rightarrow CD \\perp (SHE).$ Suy ra $HF \\perp CD$ \\quad $(4)$<br>Từ $(2)$, $(4)$ $\\Rightarrow HF\\perp (SCD)$ tại $F$.<br>$\\Rightarrow {d}\\left(H,(SCD)\\right)=HF.$<br>\\noindent   Xét tứ giác $ABCH$ vuông tại $A$, $B$ có $BC \\parallel AH$ và $AB=BC=AH=\\dfrac{1}{2}AD=a$ nên $ABCH$ là hình vuông cạnh $a$ hay $CH \\perp AD$, ta được $\\triangle CDH$ vuông cân tại $H$ có $HE=\\dfrac{1}{2}CD=\\dfrac{a\\sqrt{2}}{2}$.<br>Do đó ${d}\\left(H,(SCD)\\right)=HF=\\dfrac{HE \\cdot SH}{\\sqrt{HE^2 + SH^2}}= \\dfrac{\\dfrac{a\\sqrt{2}}{2} \\cdot \\dfrac{a\\sqrt{6}}{2}}{\\sqrt{\\left(\\dfrac{a\\sqrt{2}}{2}\\right)^2 + \\left(\\dfrac{a\\sqrt{6}}{2}\\right)^2}} = \\dfrac{a\\sqrt{6}}{4}$.<br>Vậy ${d}\\left(B,(SCD)\\right)=\\dfrac{a\\sqrt{6}}{4}$.<br><b>Cách khác tính</b> $\\boldsymbol{{d}\\left(H,(SCD)\\right)}$.<br>Xét tứ diện $SHCD$ là tam diện vuông tại $H$ nên  $$\\dfrac{1}{{d}^2\\left(H,(SCD)\\right)}=\\dfrac{1}{HC^2}+\\dfrac{1}{HD^2}+\\dfrac{1}{HS^2}=\\dfrac{1}{a^2}+\\dfrac{1}{a^2}+\\dfrac{1}{\\left(\\dfrac{a\\sqrt{6}}{2}\\right)^2}.$$  Suy ra ${d}\\left(H,(SCD)\\right)=\\dfrac{a\\sqrt{6}}{4}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Đề TT L3, THPT Chuyên Lam Sơn, Sở Thanh Hóa, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy là hình vuông cạnh $a$, mặt bên $SAB$ là tam giác đều và nằm trong mặt phẳng vuông góc với mặt phẳng đáy. Khoảng cách từ $A$ đến mặt phẳng $(SBD)$ bằng", "choices": ["$\\dfrac{\\sqrt{21}a}{14}$", "$\\dfrac{\\sqrt{21}a}{28}$", "$\\dfrac{\\sqrt{2}a}{2}$", "$\\dfrac{\\sqrt{21}a}{7}$"], "correctIndex": 3, "explain": "Gọi $H$, $O$, $I$ lần lượt là trung điểm của $AB$, $BD$, $BO$.<br>Khi đó $SH$ là đường cao của tam giác đều $SAB$ nên $SH=\\dfrac{a\\sqrt{3}}{2}$, $SH\\perp AB$. Tiếp đến $(SAB)\\perp (ABCD)$ và $(SAB)\\cap (ABCD)=AB$ nên $$SH\\perp (ABCD)\\Rightarrow SH\\perp BD.$$  Dễ thấy $HI=\\dfrac{AO}{2}=\\dfrac{a\\sqrt{2}}{4}$ và $HI\\perp BD$.<br>Suy ra $BD\\perp (SHI)$.  \\noindent<br>Gọi $K$ là hình chiếu vuông góc của $H$ trên $SI$ thì $HK\\perp SI$ và $HK\\perp BD$ nên $HK\\perp (SBD)$.<br>Do đó ${d}(H,(SBD))=HK=\\sqrt{\\dfrac{HS^2\\cdot HI^2}{HS^2+HI^2}}=\\dfrac{a\\sqrt{21}}{14}$.<br>Ta có $AB\\cap (SBD)=B$ nên $\\dfrac{{d}(A,(SBD))}{{d}(H,(SBD))}=\\dfrac{AB}{HB}=2$.<br>Vậy ${d}(A,(SBD))=2HK=2\\cdot\\dfrac{a\\sqrt{21}}{14}=\\dfrac{a\\sqrt{21}}{7}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử TNTHPT, Trường THPT Nguyễn Huệ -Daklak, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy là hình vuông, $AB=a$, $SA$ vuông góc với mặt phẳng đáy và $SA=2a$. Gọi $M$ là trung điểm của $CD$, khoảng cách từ điểm $M$ đến mặt phẳng $(SBD)$ bằng", "choices": ["$\\dfrac{a}{2}$", "$\\dfrac{a}{3}$", "$\\dfrac{2a}{3}$", "$\\dfrac{a}{\\sqrt{2}}$"], "correctIndex": 1, "explain": "Gọi $O$ là tâm hình vuông $ABCD$, $K$ là hình chiếu vuông góc của $A$ lên cạnh $SO$.<br>Do $BD\\perp AC$ và $BD\\perp SA$ nên $BD\\perp AK$ (vì $AK\\subset(SAC)$).<br>Do $AK\\perp SO$ và $AK\\perp BD$ nên $AK\\perp(SDB)$.<br>Suy ra, ${d}(A,(SBD))=AK$.<br>Ta có ${d}(M,(SBD))=\\dfrac{1}{2}{d}(C,(SBD))=\\dfrac{1}{2}{d}(A,(SBD))=\\dfrac{1}{2}AK$.<br>\\noindent Tam giác $SAO$ vuông tại $A$ có  \\[\\dfrac{1}{AK^2}=\\dfrac{1}{SA^2}+\\dfrac{1}{AO^2}=\\dfrac{1}{4a^2}+\\dfrac{2}{a^2}=\\dfrac{9}{4a^2}.\\]  Vậy ${d}(M,(SBD))=\\dfrac{AK}{2}=\\dfrac{\\dfrac{2a}{3}}{2}=\\dfrac{a}{3}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[line cap=round,line join=round,font=\\footnotesize,>=stealth,scale=1]\n\t\t\t\t\t\\fill (0,0) coordinate [label=above left:$A$] (A) circle(1pt)\n\t\t\t\t\t(0:3) coordinate [label=below right:$D$] (D) circle(1pt)\n\t\t\t\t\t(90:2) coordinate [label=above right:$S$] (S) circle(1pt)\n\t\t\t\t\t(-40:2.5) coordinate [label=below right:$C$] (C) circle(1pt)\n\t\t\t\t\t($(A)+(C)-(D)$) coordinate [label=below:$B$] (B) circle(1pt)\n\t\t\t\t\t($(D)!0.5!(C)$) coordinate [label=right:$M$] (M) circle(1pt)\n\t\t\t\t\t($(A)!0.5!(C)$) coordinate [label=below:$O$] (O) circle(1pt)\n\t\t\t\t\t($(S)!0.6!(O)$) coordinate (K) node[shift={(160:2ex)}]{$K$}  circle(1pt);\n\t\t\t\t\t\\draw (S)--(D)--(C) (B)--(S)--(C)--(B);\n\t\t\t\t\t\\draw[dashed] (B)--(A)--(S)--(O) (C)--(A)--(D)--(B) (K)--(A);\n\t\t\t\\end{tikzpicture}</script></div>", "nguon": "Đề thi thử trường THPT Thanh Miện & Đoàn Thượng - Hải Dương năm 2020-2021 Lần 3"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho lăng trụ đứng $ABC.A'B'C'$ có đáy $ABC$ là tam giác đều cạnh $a$ và $AA'=2a$. Gọi $M$ là trung điểm của $CC'$. Khoảng cách từ $M$ đến mặt phẳng $(A'BC)$ bằng", "choices": ["$\\dfrac{a\\sqrt{57}}{19}$", "$\\dfrac{2\\sqrt{5}a}{5}$", "$\\dfrac{2\\sqrt{57}a}{19}$", "$\\dfrac{a\\sqrt{5}}{5}$"], "correctIndex": 0, "explain": "Ta có $M$ là trung điểm $CC'$.<br>Nên ${d}(M,(A'BC))=\\dfrac{1}{2}{d}(C,(A'BC))=\\dfrac{1}{2}{d}(A,(A'BC))$.<br>Gọi $E$, $H$ lần lượt là hình chiếu của $A$ lên $BC$, $A'E$.<br>Ta có $\\heva{&BC\\perp AA'\\\\&BC\\perp AE}\\Rightarrow BC\\perp AH$.<br>Mà $AH\\perp A'E\\Rightarrow AH\\perp (A'BC)$.<br>Do đó ${d}(A,(A'BC))=AH$.<br>Tam giác $ABC$ đều cạnh $a$ nên $AE=\\dfrac{a\\sqrt{3}}{2}$.<br>Xét tam giác vuông $AA'E$ có <br>$$\\dfrac{1}{AH^2}=\\dfrac{1}{AA'^2}+\\dfrac{1}{AE^2}\\Rightarrow AH=\\sqrt{\\dfrac{AA'^2\\cdot AE^2}{AA'^2+AE^2}}=\\dfrac{2a\\sqrt{57}}{19}.$$  Vậy ${d}(M,(A'BC))=\\dfrac{1}{2}{d}(A,(A'BC))=\\dfrac{1}{2}\\cdot AH=\\dfrac{a\\sqrt{57}}{19}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\begin{scope}[scale=.8]\n\t\t\t\t\t\t\\path \n\t\t\t\t\t\t(0,0) coordinate (A)\n\t\t\t\t\t\t+(1,-2) coordinate (B)\n\t\t\t\t\t\t+(5,0) coordinate (C)\n\t\t\t\t\t\t($(B)!.5!(C)$) coordinate (E)\n\t\t\t\t\t\t;\n\t\t\t\t\t\t\\foreach \\x/\\y in{A/A',B/B',C/C'} \\path ($(\\x)+(0,4)$) coordinate (\\y);\n\t\t\t\t\t\t\\coordinate (M) at ($(C)!.5!(C')$);\n\t\t\t\t\t\t\\coordinate (H) at ($(A')!.7!(E)$);\n\t\t\t\t\t\t\\draw (A)--(B)--(C)--(C')--(A')--cycle (B)--(B') (A')--(B')--(C') (A')--(B);\n\t\t\t\t\t\t\\draw[dashed] (A)--(C)--(A') (A)--(E) (A')--(E) (A)--(H);\n\t\t\t\t\t\t\\foreach \\x/\\y/\\z in {A/E/B,A/H/E} \\draw ($(\\y)!5pt!(\\x)$)--($(\\y)!2!($($(\\y)!5pt!(\\x)$)!.5!($(\\y)!5pt!(\\z)$)$)$)--($(\\y)!5pt!(\\z)$); \n\t\t\t\t\t\t\\foreach \\p/\\r in {A/180,B/-90,C/0,A'/180,B'/-45,C'/0,M/0,E/-45,H/0}\n\t\t\t\t\t\t\\fill (\\p) circle (1pt) node[shift={(\\r:3mm)}]{$\\p$};\n\t\t\t\t\t\\end{scope}\n\t\t\t\t\\end{tikzpicture}</script></div>", "nguon": "Thi thử, THPT Quảng Xương 2 - Thanh Hóa, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có $SA \\perp (ABCD)$, đáy $ABCD$ là hình vuông, biết $AB=1$, $SA=2$. Khoảng cách từ $C$ đến mặt phẳng $(SBD)$ bằng", "choices": ["$\\dfrac{\\sqrt{2}}{2}$", "$\\dfrac{2}{3}$", "$\\dfrac{3}{2}$", "$\\sqrt{2}$"], "correctIndex": 1, "explain": "Gọi $O$ là tâm của hình vuông $ABCD$, khi đó $AO=CO$ và $AC \\cap(SBD)=\\{O\\}$. <br>Ta có $\\heva{&SA \\perp (ABCD)\\\\& BD \\subset (ABCD)} \\Rightarrow SA \\perp BD$.<br>Mặt khác $ABCD$ là hình vuông nên $AC \\perp BD$ hay $AO \\perp BD$.<br>Khi đó $\\heva{&BD \\perp SA \\\\& BD \\perp AO \\\\&SA, AO \\subset (SAO)}\\Rightarrow \\heva{&(SAO) \\perp(SBD). \\\\\n\t\t\t\t&(SAO) \\cap(SBD)=SO.}$<br>Gọi $H$ là hình chiếu vuông góc của $A$ trên $(SBD)$ $(H \\in SO) \\Rightarrow {d}(A,(SBD))=AH.$<br>Ta có $\\dfrac{{d}(C, (SBD))}{{d}(A, (SBD))}=\\dfrac{CO}{AO}=1.$ Suy ra ${d}(C,(SBD))={d}(A,(SBD))=AH.$<br>Tính được $AC=1 \\cdot \\sqrt{2}=\\sqrt{2}$.<br>Trong tam giác $SAO$ vuông tại $A$, ta có:   $$\\dfrac{1}{AH^{2}}=\\dfrac{1}{AO^{2}}+\\dfrac{1}{SA^{2}}  =\\dfrac{1}{\\left(\\tfrac{AC}{2}\\right)^{2}}+\\dfrac{1}{2^{2}}=\\dfrac{1}{\\left(\\dfrac{\\sqrt{2}}{2}\\right)^{2}}+\\dfrac{1}{2^{2}}=\\dfrac{9}{4}.$$  $\\Rightarrow A H=\\dfrac{2}{3} \\Rightarrow d(C,(S B D))=\\dfrac{2}{3}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử, Sở GD và ĐT - Kiên Giang, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp tam giác đều $S.ABC$ có đáy $ABC$ với cạnh đáy bằng $a $. $ G$ là trọng tâm $ABC$. Góc giữa mặt bên với mặt đáy bằng $60^{\\circ}$. Khoảng cách từ điểm $G$ đến mặt phẳng $(SBC)$ bằng", "choices": ["$\\dfrac{a}{4}$", "$\\dfrac{3 a}{4}$", "$\\dfrac{3 a}{2}$", "$\\dfrac{a}{2}$"], "correctIndex": 0, "explain": "Gọi $ I $ là trung điểm $ BC $.<br>Trong $ (SAI) $, kẻ $ GH\\perp SI $.<br>Ta có $ \\heva{&BC \\perp AI \\\\ &BC \\perp SI} $ <br>suy ra $ BC \\perp(SAI) \\Rightarrow BC \\perp GH$.<br>Mà $SI \\perp GH \\Rightarrow GH \\perp(SBC) \\Rightarrow GH={d}(G,(SBC))$.<br>Ta có $ \\heva{&(SBC)\\cap (ABC)=BC \\\\ &SI \\subset (SBC),\\,SI \\perp BC\\\\&AI \\subset (ABC),\\,AI \\perp BC} $ suy ra <br>$((SBC),(ABC))=(SI,AI)=\\widehat{SIA}=\\widehat{SIG}=60^\\circ$.<br>\\noindent   Ta có $ GI=\\dfrac{1}{3}AI =\\dfrac{a\\sqrt{3}}{6}\\Rightarrow GH=GI\\cdot \\sin 60^\\circ =\\dfrac{a\\sqrt{3}}{6}\\cdot \\dfrac{\\sqrt{3}}{2}=\\dfrac{a}{4} $.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=.7, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\path\n\t\t\t\t\t(-1,0)coordinate(A)\n\t\t\t\t\t(2,-2)coordinate(B)\n\t\t\t\t\t(7,0)coordinate(C)\n\t\t\t\t\t($(C)!1/2!(B)$)coordinate(I)\n\t\t\t\t\t($(C)!1/2!(B)$)coordinate(N)\n\t\t\t\t\t($(A)!2/3!(I)$)coordinate(G)\n\t\t\t\t\t($(G)+(0,6)$)coordinate(S)\n\t\t\t\t\t($(S)!2/3!(I)$)coordinate(H)\n\t\t\t\t\t;\n\t\t\t\t\t\\draw[dashed](C)--(A)--(I) (C)--(N) (S)--(G)--(H);\n\t\t\t\t\t\\draw (I)--(S)--(B) (S)--(A)--(B)--(C)--cycle;\n\t\t\t\t\t\\foreach \\p/\\g in {A/180,C/0,B/-90,S/90,G/-45,I/-45,H/0}\n\t\t\t\t\t\\draw[fill=black] (\\p) circle(.5pt) +(\\g:.3) node{$\\p$};\n\t\t\t\t\t\\foreach \\i/\\j/\\k/\\t in {B/A/C/6,G/S/C/6,H/G/I/6}{\n\t\t\t\t\t\t\\def\\dgiua{\\i}\\def\\dmot{\\j}\\def\\dhai{\\k}\\def\\tyso{\\t pt}\n\t\t\t\t\t\t\\draw ($(\\dgiua)!\\tyso!(\\dmot)$)--($(\\dgiua)!2!($($(\\dgiua)!\\tyso!(\\dmot)$)!.5!($(\\dgiua)!\\tyso!(\\dhai)$)$)$)--($(\\dgiua)!\\tyso!(\\dhai)$);}\n\t\t\t\t\\end{tikzpicture}</script></div>", "nguon": "Thi thử, THPT Hải Lăng (Quảng Trị) 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy là hình vuông cạnh $2a$, tam giác $SAB$ cân tại $S$ và nằm trong mặt phẳng vuông góc với đáy. Góc giữa hai mặt phẳng $(SCD)$ và $(ABCD)$ bằng $\\varphi$ và $\\sin \\varphi =\\dfrac{\\sqrt{5}}{5}$. Khoảng cách từ điểm $A$ đến mặt phẳng $(SCD)$ bằng", "choices": ["$\\dfrac{a}{5}$", "$\\dfrac{2a}{5}$", "$\\dfrac{2\\sqrt{5}a}{5}$", "$\\dfrac{a\\sqrt{5}}{5}$"], "correctIndex": 2, "explain": "Gọi $H$ là trung điểm $AB$. Do tam giác $SAB$ cân tại $S$ $\\Rightarrow SH \\perp AB$.<br>Mà $(SAB) \\perp (ABCD) \\Rightarrow SH \\perp (ABCD)$.<br>Kẻ $HK \\perp CD \\Rightarrow CD \\perp (SHK) \\Rightarrow CD \\perp SK$<br>$\\Rightarrow [(SCD),(ABCD)]=(HK,SK)=\\widehat{SKH}=\\varphi$.<br>Ta có $HA \\parallel (SCD) \\Rightarrow {d}(A,(SCD))={d}(H,(SCD))$.<br>Kẻ $HI \\perp SK \\Rightarrow HI \\perp (SCD) \\Rightarrow {d}(H,(SCD))=HI=\\sin \\varphi \\cdot HK=\\dfrac{2\\sqrt{5}a}{5}$.<br>Vậy ${d}(A,(SCD))=\\dfrac{2\\sqrt{5}a}{5}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử Lần 3, Chuyên Bắc Ninh, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hộp đứng $ABCD.A'B'C'D'$ có tất cả các cạnh bằng $2a$ và $\\widehat{ABC}=60^\\circ $ . Gọi $M$ là trung điểm của cạnh $AA'$. Khoảng cách từ $D'$ đến mặt phẳng $(MBC)$ bằng", "choices": ["$a$", "$\\dfrac{a\\sqrt{3}}{3}$", "$\\dfrac{a\\sqrt{5}}{2}$", "$\\dfrac{a\\sqrt{3}}{2}$"], "correctIndex": 3, "explain": "Vì $A'D'\\parallel (MBC)$ nên ${d}(D',(MBC))={d}(A',(MBC))$.<br>Mà $$\\dfrac{{d}(A',(MBC))}{{d}(A,(MBC))}=\\dfrac{A'M}{AM}=1\\Rightarrow {d}(A',(MBC))={d}(A,(MBC)).$$  Gọi $I$, $H$ lần lượt là hình chiếu vuông góc của $A$ trên $BC$ và $MI$.<br>Từ giả thiết ta suy ra tam giác $ABC$ đều, nên $I$ là trung điểm của $BC$ và $AI=a\\sqrt{3}$.<br>Ta có $\\heva{&BC\\perp AI\\\\&BC\\perp AM}\\Rightarrow BC \\perp (MAI) \\Rightarrow BC \\perp AH \\quad\\quad (1)$.<br>Mặt khác ta có $AH \\perp MI \\quad\\quad(2).$<br>Từ $(1)$ và $(2)$ suy ra $AH \\perp (MBC)\\Rightarrow \n\t\t\t{d}(A,(MBC))=AH$.<br>Trong tam giác vuông $MAI$ với $AH$ là đường cao, ta có  $$\\dfrac{1}{AH^2}=\\dfrac{1}{AM^2}+\\dfrac{1}{AI^2}=\\dfrac{1}{a^2}+\\dfrac{1}{3a^2}=\\dfrac{4}{3a^2}.$$  Suy ra $AH^2=\\dfrac{3a^2}{4}\\Rightarrow AH= \\dfrac{a\\sqrt{3}}{2}$.<br>Vậy ${d}(D',(MBC))=\\dfrac{a\\sqrt{3}}{2}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử lần 2, Kênh VTV7, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABC$ có $SA\\perp(ABC)$, $AB=4$, $AC=3,BC=5$. Khoảng cách từ điểm $B$ đến $(SAC)$ bằng", "choices": ["$5$", "$4$", "$3$", "$2\\sqrt{3}$"], "correctIndex": 1, "explain": "Từ giả thiết suy ra $ABC$ là tam giác vuông tại $A$.<br>Như vậy ${d}\\left(B,(SAC)\\right)=BA=4$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử THPT Yên Phong 1 - Bắc Ninh, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp tứ giác đều $S.ABCD$ có độ dài cạnh đáy bằng $a$ và độ dài cạnh bên $a \\sqrt{2}$ .  Khoảng cách từ điểm $S$ đến mặt phẳng $(ABCD)$ bằng", "choices": ["$a \\sqrt{3}$", "$\\dfrac{a \\sqrt{2}}{3}$", "$\\dfrac{a \\sqrt{3}}{2}$", "$\\dfrac{a \\sqrt{6}}{2}$"], "correctIndex": 3, "explain": "Ta có  \\begin{eqnarray*}  {d}[S,(ABCD)]&=&SO  <br>&=&\\sqrt{SD^2-OD^2}  <br>&=&\\sqrt{SD^2-\\dfrac{BD^2}{4}}  <br>&=&\\sqrt{(a\\sqrt 2)^2 -\\dfrac{(a\\sqrt 2)^2}{4}}  <br>&=& \\dfrac{a\\sqrt 6}{2}.  \\end{eqnarray*}", "nguon": "Đề TT L3, THPT Thành Nhân, Sở TP. HCM, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tứ diện $ABCD$ có $AB$, $AC$, $AD$ đôi một vuông góc với nhau và $AB = AC = AD = a$. Tính khoảng cách từ $A$ tới mặt phẳng $(BCD)$.", "choices": ["$ a\\sqrt{3}$", "$ \\dfrac{a\\sqrt{2}}{2} $", "$a\\sqrt{2} $", "$\\dfrac{a\\sqrt{3}}{3}$"], "correctIndex": 3, "explain": "Gọi $I$ là trung điểm của $DC \\Rightarrow AI \\perp DC$ mà $DC \\perp AB$ nên $DC \\perp (BAI)$.<br>Gọi $H$ là hình chiếu vuông góc của $A$ lên $BI$, khi đó $DC \\perp AH$. Vậy $AH \\perp (BDC) \\Rightarrow {d}(A,(BDC)) = AH$.<br>Xét tam giác $ADC$ vuông tại $A$, $AI$ là đường cao  $$\\dfrac{1}{AI^2} = \\dfrac{1}{AD^2} + \\dfrac{1}{AC^2} = \\dfrac{1}{a^2} + \\dfrac{1}{a^2} = \\dfrac{2}{a^2}.$$  Xét tam giác $BAI$ vuông tại $A$, $AH$ là đường cao thì  $$\\dfrac{1}{AH^2} = \\dfrac{1}{AB^2} + \\dfrac{1}{AI^2} = \\dfrac{3}{a^2} \\Rightarrow AH = \\dfrac{a\\sqrt{3}}{3}.$$  Vậy ${d}(A,(BDC)) = AH = \\dfrac{a\\sqrt{3}}{3}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử, THPT Nguyễn Đăng Đạo - Bắc Ninh"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Chóp $S.ABCD$ có đáy là hình bình hành, $SA$ vuông góc với đáy. Biết khoảng cách từ $A$ đến $(SBD)$ bằng $\\dfrac{6a}{7}$. Tính khoảng cách từ $C$ đến mặt phẳng $(SBD)$.", "choices": ["$\\dfrac{12a}{7}$", "$\\dfrac{3a}{7}$", "$\\dfrac{4a}{7}$", "$\\dfrac{6a}{7}$"], "correctIndex": 3, "explain": "Gọi $O$ là giao của $AC$ và $BD$, ta có  \\[\\dfrac{{d}\\left(A,(SBD)\\right)}{{d}\\left(C,(SBD)\\right)}=\\dfrac{OA}{OC}=1.\\]  Suy ra ${d}\\left(C,(SBD)\\right)={d}\\left(A,(SBD)\\right)=\\dfrac{6a}{7}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\def\\a{2.25}\n\t\t\t\t\t\\path(0,0)coordinate(A)++(\\a,0)coordinate(B)(-135:0.65*\\a)coordinate(D)++(0:\\a)coordinate(C)(0,\\a)coordinate(S)($(A)!0.5!(C)$)coordinate(O);\n\t\t\t\t\t\\draw(S)--(B)--(C)--(D)--(S)(S)--(C);\n\t\t\t\t\t\\draw[dashed](D)--(A)--(B)(S)--(A)--(C)(B)--(D)(S)--(O);\n\t\t\t\t\t\\foreach \\d/\\g in{A/180,B/0,C/-90,D/-90,S/90,O/-90}\n\t\t\t\t\t\\draw[fill=black](\\d)circle(1pt)node[shift={(\\g:0.35)}]{$\\d$};\n\t\t\t\t\\end{tikzpicture}</script></div>", "nguon": "Đề thi thử TN THPT môn Toán năm 2021, THPT Mai Anh Tuấn, Thanh Hóa lần 1"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy là hình thoi tâm $O$, $SO\\perp (ABCD$, $SO=\\dfrac{a\\sqrt{6}}{3}$ và $BC=SB=a$ . Khoảng cách từ điểm $O$ đến mặt phẳng $\\left( SBC \\right)$ bằng", "choices": ["$\\dfrac{2\\text{a}\\sqrt{3}}{3}$", "$\\dfrac{a\\sqrt{3}}{6}$", "$\\dfrac{a\\sqrt{6}}{6}$", "$\\dfrac{a\\sqrt{6}}{2}$"], "correctIndex": 2, "explain": "Ta có $OB=\\sqrt{SB^2-SO^2}=\\dfrac{a\\sqrt{3}}{3}$.<br>Suy ra $OC=\\sqrt{BC^2-OB^2}=\\dfrac{a\\sqrt{6}}{3}$.<br>Kẻ $OH\\perp BC$. Khi đó $\\heva{& OH\\perp BC\\\\& SO\\perp BC}$<br>$\\Rightarrow BC\\perp (SOH)\\Rightarrow (SBC)\\perp (SOH)$.<br>Kẻ $OK\\perp SH\\Rightarrow OK\\perp (SBC)\\Rightarrow {d}(O,(SBC))=OK$. <br>\\noindent Khi đó $O.SBC$ là tứ diện vuông nên $\\dfrac{1}{OK^2}=\\dfrac{1}{OB^2}+\\dfrac{1}{OC^2}+\\dfrac{1}{SO^2}=\\dfrac{6}{a^2}\\Rightarrow OK=\\dfrac{a\\sqrt{6}}{6}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\def\\a{3} \\def\\b{2} \\def\\h{2.2}\n\t\t\t\t\t\\path\n\t\t\t\t\t(0:0) coordinate (A)\n\t\t\t\t\t(0:\\a) coordinate (B)\n\t\t\t\t\t(220:\\b) coordinate (D)\n\t\t\t\t\t($(B)+(D)-(A)$) coordinate (C)\n\t\t\t\t\t($(A)!1/2!(C)$) coordinate (O)\n\t\t\t\t\t($(O)+(90:\\h)$) coordinate (S)\n\t\t\t\t\t($(B)!2/2.6!(C)$) coordinate (H)\n\t\t\t\t\t($(S)!2/3!(H)$) coordinate (K)\n\t\t\t\t\t;\n\t\t\t\t\t\\draw (D)--(C)--(B)--(S)--(D) (H)--(S)--(C);\n\t\t\t\t\t\\draw[dashed] (O)--(S)--(A)--(B) (C)--(A)--(D)--(B) (K)--(O)--(H);\n\t\t\t\t\t\\foreach \\x/\\g in {A/160,B/0,C/-90,D/-90,S/90,O/-90,H/-30,K/0}\n\t\t\t\t\t\\fill[black] (\\x) circle(1pt) ($(\\x)+(\\g:3mm)$) node{$\\x$};\t\t\n\t\t\t\t\\end{tikzpicture}</script></div>", "nguon": "Thi thử, Sở GD và ĐT - Hưng Yên lần 2, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp tứ giác $S.ABCD$ có đáy là hình chữ nhật tâm $O$. Biết rằng $SO$ vuông góc với mặt phẳng đáy và $AB=2a;AD=a;SO=a\\sqrt{3}$. Khoảng cách từ $O$ tới mặt phẳng $\\left(SBC\\right)$ là", "choices": ["$\\dfrac{a\\sqrt{3}}{2}$", "$\\dfrac{a\\sqrt{13}}{2}$", "$a\\sqrt{3}$", "$a$"], "correctIndex": 0, "explain": "Gọi $M$ là trung điểm của $BC$. Khi đó $OM\\perp BC$ mà $BC\\perp SO$ nên suy ra $BC\\perp\\left(SOM\\right)$.<br>Trong $\\left(SOM\\right)$, kẻ $OH\\perp SM$. Suy ra $BC\\perp OH$.<br>Khi đó $OH\\perp\\left(SBC\\right)$ nên $\\mathrm{d}\\left(O, (SBC)\\right)=OH$.<br>Tam giác $SOM$ vuông tại $O$ có $OH$ là đường cao nên  $$OH=\\dfrac{SO\\cdot OM}{\\sqrt{S{O^2}+O{M^2}}}=\\dfrac{a\\sqrt{3}\\cdot a}{\\sqrt{\\left(a\\sqrt{3}\\right)^2+a^2}}=\\dfrac{a\\sqrt{3}}{2}.$$\\noindent<br>Vậy $\\mathrm{d}\\left(O, (SBC)\\right)=\\dfrac{a\\sqrt{3}}{2}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử lần 2, Sở GD và ĐT - Bắc Giang, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hộp chữ nhật $ABCD.A'B'C'D'$ có $AB=a \\sqrt{3}$, $AD=a$. Khoảng cách từ $A$ đến mặt phẳng $\\left(BDD'B'\\right)$ bằng", "choices": ["$\\dfrac{a\\sqrt{3}}{2}$", "$2a$", "$a\\sqrt{3}$", "$\\dfrac{a\\sqrt{2}}{2}$"], "correctIndex": 0, "explain": "Kẻ $AO \\perp BD$, $O \\in BD$.<br>Ta có $\\heva{&AO \\perp BD \\\\ &AO \\perp BB'} \\Rightarrow AO \\perp\\left(BDD'B'\\right)$<br>$\\Rightarrow \\mathrm{d}\\left(A,\\left(BDD'B'\\right)\\right)=AO$.<br>Trong tam giác vuông $ABD$ ta có<br>$\\dfrac{1}{AO^{2}}=\\dfrac{1}{AB^{2}}+\\dfrac{1}{AD^{2}}=\\dfrac{1}{a^{2}}+\\dfrac{1}{3a^{2}} \\Rightarrow AO=\\dfrac{a\\sqrt{3}}{2}$.<br>Vậy $\\mathrm{d}\\left(A,\\left(BDD'B'\\right)\\right)=\\dfrac{a \\sqrt{3}}{2}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\def\\r{3.5}\n\t\t\t\t\t\\path\n\t\t\t\t\t(0:0) coordinate (A)\n\t\t\t\t\t++(0:\\r) coordinate (B)\n\t\t\t\t\t++(30:0.5*\\r) coordinate (C)\n\t\t\t\t\t($(A)+(C)-(B)$) coordinate (D)\n\t\t\t\t\t($(B)!0.7!(D)$) coordinate (O)\n\t\t\t\t\t\\foreach \\x in {A,B,C,D}{\n\t\t\t\t\t\t(\\x)++(90:\\r) coordinate (\\x')\n\t\t\t\t\t}\n\t\t\t\t\t;\n\t\t\t\t\t\\draw \n\t\t\t\t\t(A)--(B)--(B')--(A')--cycle\n\t\t\t\t\t(A')--(D')--(C')--(B')--(D')\n\t\t\t\t\t(B)--(C)--(C')\n\t\t\t\t\t;\n\t\t\t\t\t\\draw[dashed]\n\t\t\t\t\t(C)--(A)--(D)--cycle\n\t\t\t\t\t(D)--(D') (A)--(O)\n\t\t\t\t\t(D)--(B)\n\t\t\t\t\t;\n\t\t\t\t\t\\foreach \\x/\\g in \n\t\t\t\t\t{A/-135,B/-45,C/0,D/160,A'/150,B'/-30,C'/30,D'/135}\n\t\t\t\t\t\\draw [fill=black] (\\x) circle (.03)+ (\\g:.3) \n\t\t\t\t\tnode {$\\x$};\n\t\t\t\t\t\\draw [fill=black] (O) circle (.03)+ (10:.4) \n\t\t\t\t\tnode {$O$};\n\t\t\t\\end{tikzpicture}</script></div>", "nguon": "Đề thi thử sở GD-ĐT Hòa Bình"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp tam giác $S.ABC$ có $SA$ vuông góc với mặt phẳng đáy $(ABC)$ và $SA=3a$. Diện tích tam giác $ABC$ bằng $2a^{2}$, $BC=a$. Khoảng cách từ $S$ đến $BC$ bằng", "choices": ["$3a$", "$2a$", "$5a$", "$4a$"], "correctIndex": 2, "explain": "Trong mặt phẳng $(ABC)$, gọi $I$ là chân đường cao hạ từ $A$ của $\\triangle ABC$.<br>Theo giả thiết, ta có $SA \\perp (ABC)$ nên $SA \\perp BC$ và $SA \\perp AI$.<br>Khi đó $\\heva{BC \\perp SA \\\\ BC \\perp AI} \\Rightarrow BC \\perp SI$ tại $I$. Suy ra $\\mathrm{d}\\left(S, BC\\right)=SI$.<br>Mặt khác, ta có $S_{\\triangle ABC}=\\dfrac{1}{2}\\cdot AI\\cdot BC$ nên   \\[AI=\\dfrac{2S_{\\triangle ABC}}{BC}=\\dfrac{2\\cdot 2 a^2}{a}=4a.\\]  Xét $\\triangle ABC$ vuông tại $A$, ta có   \\[SI^2=SA^2+AI^2=(3a)^2+(4a)^2=25a^2.\\]  Suy ra $\\mathrm{d}\\left(S, BC\\right)=SI=5a$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "2-TT-Sở GD & ĐT tỉnh Lai Châu - 21"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp tam giác đều $S.ABC$ có cạnh đáy bằng $a$ và khoảng cách từ $A$ đến mặt phẳng $(SBC)$ bằng $\\dfrac{3a}{4}$ . Góc giữa mặt phẳng $(SBC)$ và mặt đáy $(ABC)$ bằng", "choices": ["$30^\\circ$", "$45^\\circ$", "$60^\\circ$", "$90^\\circ$"], "correctIndex": 2, "explain": "Gọi $I$ là trung điểm của $BC$ và $O$ là trọng tâm của $\\triangle ABC$. Khi đó,  \\[ \\heva{& BC\\perp AI\\\\ & BC \\perp SO} \\Rightarrow BC \\perp (SAI) \\Rightarrow BC\\perp SI.\\]  Khi đó, góc giữa hai mặt phẳng $(SBC)$ và mặt đáy $(ABC)$ là góc $\\widehat{SIO}$.  <br>Trong mặt phẳng $(SAI)$, dựng $AH\\perp SI$, $H\\in SI $.<br>\\noindent  Do $BC\\perp (SAI)$ nên $(SBC) \\perp (SAI)$. Suy ra $AH \\perp (SBC)$. Vì vậy  \\[ AH =\\mathrm{d}(A, (SBC))=\\dfrac{3a}{4}.\\]  Xét tam giác $\\triangle AHI$ vuông tại $H$, ta có  \\[\\sin \\widehat{AIH} = \\dfrac{AH}{AI} =\\dfrac{\\dfrac{3a}{4}}{\\dfrac{a\\sqrt{3}}{2}}=\\dfrac{\\sqrt{3}}{2} \\Rightarrow \\widehat{AIH} =60^\\circ. \\]  Vậy góc giữa hai mặt phẳng $(SBC)$ và $(ABC)$ là $60^\\circ$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử THPT chuyên Hùng Vương - Gia Lai, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy $ABCD$ là hình thang có đáy lớn là $AD$, các đường thẳng $SA$, $AC$ và $CD$ đôi một vuông góc với nhau; $SA= AC=CD=a\\sqrt{2}$ và $AD=2BC$. Khoảng cách giữa $SB$ và $CD$ bằng", "choices": ["$\\dfrac{a\\sqrt{10}}{5}$", "$\\dfrac{a\\sqrt{10}}{2}$", "$\\dfrac{a\\sqrt{5}}{2}$", "$\\dfrac{a\\sqrt{5}}{5}$"], "correctIndex": 0, "explain": "Tam giác $ACD$ vuông cân tại $C$ nên \\[AD=AC\\sqrt{2} = 2a \\Rightarrow BC=a. \\]  Gọi $M$ là trung điểm của $AD$. Ta có $AM=BC=a$ và $AM\\parallel BC$ nên tứ giác $ABCM$ là hình bình hành. Mà $AM\\perp MC$ suy ra tứ giác $ABCM$ là hình vuông. <br>Gọi $K$ là trung điểm của $AC$, $H$ là hình chiếu vuông góc của $A$ trên $SK$.  Ta có   \\[\n\t\t\t\t\\heva{&CD \\perp SA\\\\&CD\\perp AC} \\Rightarrow CD \\perp (SAC) \\Rightarrow CD \\perp AH.\n\t\t\t\t\\]<br>\\noindent Mà $AH \\perp SK \\Rightarrow AH \\perp (SBM) \\Rightarrow {d}(A,(SBM))= AH$. <br>Tứ giác $MBCD$ có $MD\\parallel BC$ và $MD=BC$ nên là hình bình hành, suy ra $CD \\parallel BM$. <br>Mặt khác $K$ là trung điểm của $AC$ suy ra  \\[\n\t\t\t{d}(SB,CD) = {d}(C,(SBM)) = {d}(A,(SBM)) =AH= \\dfrac{SA \\cdot AK}{\\sqrt{SA^2+AK^2}} = \\dfrac{a\\sqrt{10}}{5}.\n\t\t\t\\]<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử đợt 1, Sở Thái Nguyên, 2020-2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABCD$ có đáy $ABCD$ là hình thoi tâm $O$. Biết $AC=2\\sqrt{3}a$, $BD=2a$, $SD=\\sqrt{2}a$ và $SO$ vuông góc với mặt phẳng đáy. Khoảng cách giữa $AB$ và $SD$ bằng", "choices": ["$\\dfrac{2\\sqrt{21}}{7}a$", "$\\dfrac{\\sqrt{21}}{3}a$", "$\\dfrac{\\sqrt{21}}{7}a$", "$\\dfrac{2\\sqrt{21}}{3}a$"], "correctIndex": 0, "explain": "Từ $O$ dựng $OI\\perp CD$ tại $I$.<br>$ABCD$ là hình thoi nên tam giác $OCD$ vuông tại $O$, có $$OC=\\dfrac{1}{2}AC=a\\sqrt{3}, OD=\\dfrac{1}{2}BD=a$$ nên $OI=\\dfrac{OC\\cdot OD}{\\sqrt{OC^2+OD^2}}=\\dfrac{a\\sqrt{3}\\cdot a}{\\sqrt{3a^2+a^2}}=\\dfrac{a\\sqrt{3}}{2}$.<br>Tam giác $SOD$ vuông tại $O$, có $SD=a\\sqrt{2}$, $OD=a$ nên $$SO=\\sqrt{SD^2-OD^2}=\\sqrt{2a^2-a^2}=a.$$<br>\\noindent Từ $O$ dựng $OH \\perp SI$ tại $H$.<br>Tam giác $SOI$ vuông tại $O$, có $SO=a$, $OI=\\dfrac{a\\sqrt{3}}{2}$ nên $$OH=\\dfrac{SO\\cdot OI}{\\sqrt{SO^2+OI^2}}=\\dfrac{a\\cdot \\dfrac{a\\sqrt{3}}{2}}{\\sqrt{a^2+\\dfrac{3a^2}{4}}}=\\dfrac{a\\sqrt{21}}{7}.$$  Ta có $\\heva{&CD\\perp SO\\\\&CD\\perp OI}\\Rightarrow CD\\perp (SOI)\\Rightarrow CD \\perp OH\\Rightarrow OH \\perp (SCD)$.<br>Vì $AB \\parallel (SCD)$ nên $${\\,d}(AB,SD)={\\,d}(AB,(SCD))={\\,d}(A,(SCD))=2{\\,d}(O,(SCD))=2OH=\\dfrac{2\\sqrt{21}a}{7}.$$<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\def\\a{3} \\def\\b{2} \\def\\h{2.2}\n\t\t\t\t\t\\path\n\t\t\t\t\t(0:0) coordinate (C)\n\t\t\t\t\t(0:\\a) coordinate (B)\n\t\t\t\t\t(-72:\\b) coordinate (D)\n\t\t\t\t\t($(B)+(D)-(C)$) coordinate (A)\n\t\t\t\t\t($(C)!1/2!(A)$) coordinate (O)\n\t\t\t\t\t($(O)+(90:\\h)$) coordinate (S)\n\t\t\t\t\t($(C)!2.2/3!(D)$) coordinate (I)\n\t\t\t\t\t($(S)!3/4!(I)$) coordinate (H)\n\t\t\t\t\t;\n\t\t\t\t\t\\draw (S)--(C)--(D)--(A)--(B)--(S)--(D) (I)--(S)--(A);\n\t\t\t\t\t\\draw[dashed] (A)--(C)--(B)--(D) (S)--(O)--(H) (O)--(I);\n\t\t\t\t\t\\foreach \\x/\\g in {C/180,B/0,A/-90,D/-90,S/90,O/-90,I/180,H/180}\n\t\t\t\t\t\\fill[black] (\\x) circle(1pt) ($(\\x)+(\\g:3mm)$) node{$\\x$};\t\t\n\t\t\t\t\\end{tikzpicture}</script></div>", "nguon": "GHK2- SGD Nghệ An 20-21"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho chóp $S.ABC$, $\\triangle ABC$ vuông với $AB=AC=2$. Cạnh bên $SA$ vuông góc với đáy và $SA=3$. Gọi $M$ là trung điểm của $SC$. Tính khoảng cách giữa $AM$ và $BC$.", "choices": ["$\\dfrac{3\\sqrt{22}}{11}$", "$\\dfrac{\\sqrt{22}}{6}$", "$\\dfrac{\\sqrt{3}}{2}$", "$\\dfrac{2\\sqrt{3}}{3}$"], "correctIndex": 0, "explain": "<b>Cách 1:</b>  Dựng hình bình hành $ABCD$, khi đó $ BC \\parallel AD \\Rightarrow BC \\parallel (MAD)$.<br>Suy ra ${d}\\left(AM,BC\\right)={d}\\left(BC,(MAD)\\right)={d}\\left(C,(MAD)\\right)$.<br>Gọi $O$ là tâm hình bình hành $ABCD$.<br>Vì $ \\heva{& SM = MC \\\\ & AO = OC} \\Rightarrow \\heva{&MO \\parallel SA \\\\& OM =\\dfrac{SA}{2}=\\dfrac{3}{2}} \\Rightarrow MO \\perp (ABCD)$.<br>Trong $\\triangle AOD$ hạ $OE \\perp AD$ thì $OE= \\dfrac{{d}\\left(A,BC\\right)}{2}=\\dfrac{\\sqrt{2}}{2}$.<br>Ta có $\\heva{&MO \\perp AD \\\\ & OE \\perp AD} \\Rightarrow (MAD) \\perp (MOE)$.<br>Do đó, ${d}\\left(C,(MAD)\\right)=2{d}\\left(O,(MAD)\\right) = 2\\dfrac{OM \\cdot OE}{\\sqrt{OM^2+OE^2}}$.<br>Vậy ${d}\\left(AM,BC\\right)=2\\dfrac{\\dfrac{\\sqrt{2}}{2}\\cdot \\dfrac{3}{2}}{\\sqrt{\\dfrac{2}{4}+\\dfrac{9}{4}}}=\\dfrac{3\\sqrt{22}}{11}$.  <b>Cách 2:</b><br>Goi $N$ là trung điểm $SB$.<br>Do $\\heva{& SM=MC\\\\&SN=NB} \\Rightarrow \\heva{& MN=\\dfrac{BC}{2}=\\sqrt{2} \\\\& MN \\parallel BC.}$<br>Mà $\\triangle SAB $ vuông tại $A$ có $AN$ trung tuyến.<br>Suy ra $AN=\\dfrac{SB}{2}=\\dfrac{\\sqrt{9+4}}{2}=\\dfrac{\\sqrt{13}}{2}$.<br>Tương tự $AM=\\dfrac{SC}{2}=\\dfrac{\\sqrt{13}}{2}$.<br>Ta có $V_{S.AMN}=\\dfrac{SN}{SB}\\cdot\\dfrac{SM}{SC}\\cdot V_{S.ABC}=\\dfrac{1}{4}\\cdot \\dfrac{1}{3}\\cdot 3 \\cdot 2=\\dfrac{1}{2}$. <br>\\noindent Do $BC\\parallel MN \\Rightarrow {d}\\left(AM,BC\\right)={d}\\left(BC,(AMN)\\right)={d}\\left(B,(AMN)\\right)={d}\\left(S,(AMN)\\right)$.<br>Hơn nữa, $S_{AMN}=\\dfrac{1}{2}\\cdot MN \\cdot \\sqrt{AM^2-\\dfrac{MN^2}{4}}=\\dfrac{\\sqrt{22}}{4}$.<br>Nên ${d}\\left(S,(AMN)\\right)=\\dfrac{3V_{S.AMN}}{S_{AMN}}=\\dfrac{3\\sqrt{22}}{11}$.<br>Vậy ${d}\\left(AM,BC\\right)=\\dfrac{3\\sqrt{22}}{11}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div><br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử, THPT Lương Thế Vinh, Hà Nội, 2021 lần 2"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Chóp tứ giác đều $S.ABCD$ có cạnh đáy bằng $a$, $O$ là tâm của mặt đáy. Khoảng cách giữa $SO$ và $CD$ là", "choices": ["$\\dfrac{a}{2}$", "$a$", "$\\dfrac{\\sqrt{2}a}{2}$", "$\\sqrt{2}a$"], "correctIndex": 0, "explain": "Trong mặt phẳng $(ABCD)$ kẻ $OM\\perp  CD$ tại $M$.<br>Vì $ABCD$ là hình vuông nên $M$ là trung điểm của $CD$.<br>Mặt khác, $S.ABCD$ là chóp đều nên ta có $SO\\perp  (ABCD)\\Rightarrow SO\\perp  OM$.<br>Do đó, $OM$ là đoạn vuông góc chung của $SO$ và $CD$.<br>Suy ra khoảng cách giữa hai đường thẳng $SO$ và $CD$ là<br>${d}(SO,CD)=OM=\\dfrac{a}{2}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Thi thử, Chuyên ĐH Vinh, Nghệ An, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho lập phương $ABCD.A'B'C'D'$ có cạnh bằng $1$ . Khoảng cách giữa $AA'$ và $BD'$ bằng", "choices": ["$\\dfrac{\\sqrt{3}}{3}$", "$\\dfrac{\\sqrt{2}}{2}$", "$\\dfrac{2\\sqrt{2}}{5}$", "$\\dfrac{3\\sqrt{5}}{7}$"], "correctIndex": 1, "explain": "Vì $AA' \\parallel BB'$ nên $AA' \\parallel (BB'D')$.<br>Suy ra $\\mathrm{d}(AA',BD')= \\mathrm{d}(AA',(BB'D')) = \\mathrm{d}(A',(BB'D'))$.<br>Gọi $O$ là tâm của hình vuông $A'B'C'D'$.<br>Vì $A'O \\perp (BB'D)$ nên $\\mathrm{d}(A',(BB'D'))=A'O = \\dfrac{A'C'}{2}=\\dfrac{\\sqrt{2}}{2}$.<br>Vậy khoảng cách giữa hai đường thẳng $AA'$ và $BD'$ bằng $\\dfrac{\\sqrt{2}}{2}$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>", "nguon": "Khảo sát chất lượng lần 1, Sở Hải Phòng, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho lăng trụ đứng $ABC.A'B'C'$ có $ABC$ là tam giác vuông cân, $AB=AC=a$ và $AA'=a\\sqrt{3}$. Tính khoảng các giữa $AB'$ và $BC'$.", "choices": ["$\\dfrac{a\\sqrt{6}}{4}$", "$\\dfrac{a\\sqrt{3}}{4}$", "$\\dfrac{a\\sqrt{3}}{2}$", "$\\dfrac{a\\sqrt{15}}{5}$"], "correctIndex": 1, "explain": "Từ giả thiết, ta có chóp $C'.A'ABB'$ có đáy là hình chữ nhật và $CA'$ vuông góc với đáy.<br>Gọi $O$ là tâm của đáy $AA'B'B$ và $I$ là trung điểm của $A'C'$.<br>Trong $\\triangle A'BC'$, ta có $O$ và $I$ lần lượt là trung điểm của $A'B$ và $A'C\"$.<br>Suy ra $OI$ là đường trung bình của $\\triangle A'BC'$, nên $C'B\\parallel IO$.<br>Mà $IO\\subset(AIB')$ nên $C'B\\parallel (AIB')$.<br>\\noindent Suy ra $\\mathrm{d}(AB';BC')=\\mathrm{d}[BC';(IAB')]=\\mathrm{d}[C';(IAB')]$.<br>Do $I$ là trung điểm $A'C'$ nên $\\mathrm{d}(C';(IAB'))=\\mathrm{d}(A';(IAB'))=d$.<br>Ta thấy $A'A$, $A'I$ và $A'B'$ đôi một vuông góc với nhau nên  \\[\\dfrac{1}{d^2}=\\dfrac{1}{A'A^2}+\\dfrac{1}{A'I^2}+\\dfrac{1}{A'B'^2}=\\dfrac{1}{3a^2}+\\dfrac{4}{a^2}+\\dfrac{1}{a^2}=\\dfrac{16}{3a^2}\\Rightarrow d=\\dfrac{a\\sqrt{3}}{4}.\\]  Vậy khoảng cách cần tìm là $\\mathrm{d}(AB';BC')=d=\\dfrac{a\\sqrt{3}}{4}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.7, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\path\n\t\t\t\t\t(0,0) coordinate (A')\n\t\t\t\t\t(5,0) coordinate (B')\n\t\t\t\t\t(-2,-2) coordinate (A)\n\t\t\t\t\t($(A)+(B')-(A')$) coordinate (B)\n\t\t\t\t\t(0,4) coordinate (C')\n\t\t\t\t\t($(A')!.5!(C')$) coordinate (I)\n\t\t\t\t\t($(A')!.5!(B)$) coordinate (O)\n\t\t\t\t\t;\n\t\t\t\t\t\\pgfresetboundingbox\n\t\t\t\t\t\\draw(A)--(B)--(B')--(C')--(A)(B)--(C');\n\t\t\t\t\t\\draw[dashed](A)--(A')--(C')(A')--(B')(A)--(B')(B)--(A')(A)--(I)--(B')(I)--(O);\n\t\t\t\t\t\\foreach \\p/\\g in {B/-45,B'/0,I/150,O/-100,A'/150,C'/90,A/150}{\\node at ($(\\p)+(\\g:4mm)$) {$\\p$}; \\draw[fill=black] (\\p) circle (1pt);}\n\t\t\t\t\\end{tikzpicture}</script></div>", "nguon": "Thi thử, THPT Kinh Môn, Hải Dương, 2021"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tính khoảng cách từ $S$ đễn mặt phẳng $( ABCD )$", "choices": ["$\\dfrac{16 a}{5}$", "$\\dfrac{12 a}{5}$", "$\\dfrac{15 a}{2}$", "$\\dfrac{5 a}{2}$"], "correctIndex": 1, "explain": "", "nguon": ""}, {"question": "Tính thể tích khối chóp $S . A B C D$", "choices": ["$9 a^3$", "$\\dfrac{75 a^3}{8}$", "$\\dfrac{15 a^3}{2}$", "$18 a^3$"], "correctIndex": 2, "explain": "", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Các mặt bên của chóp là tam giác gì?", "choices": ["Tam giác thường", "Tam giác cân", "Tam giác vuông", "Tam giác đều"], "correctIndex": 1, "explain": "", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Khoảng cách từ chân đường cao của chóp đễn mặt bên là", "choices": ["$a$", "$2a$", "$3a$", "$4a$"], "correctIndex": 0, "explain": "", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tính thể tích của khôi chóp đó?", "choices": ["$V=\\dfrac{a^3 \\sqrt{3}}{9}$", "$V=\\dfrac{8 a^3 \\sqrt{2}}{3}$", "$V=\\dfrac{a^3 \\sqrt{3}}{6}$", "$V=\\dfrac{a^3 \\sqrt{3}}{4}$"], "correctIndex": 1, "explain": "", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Thể tích của khốí chóp là", "choices": ["$\\dfrac{a \\sqrt{3}}{24}$", "$\\dfrac{a \\sqrt{3}}{12}$", "$\\dfrac{a \\sqrt{3}}{6}$", "$\\dfrac{a \\sqrt{3}}{4}$"], "correctIndex": 1, "explain": "", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Khoảng cách từ điểm $D$ đến mặt phẳng $( ABC )$", "choices": ["$a$", "$\\dfrac{a \\sqrt{6}}{2}$", "$a \\sqrt{2}$", "$\\dfrac{3 a \\sqrt{2}}{4}$"], "correctIndex": 0, "explain": "", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Góc giữa hai đường thẳng $A B$ và $D E$ bằng", "choices": ["$45^{\\circ}$", "$90^{\\circ}$", "$30^{\\circ}$", "$60^{\\circ}$"], "correctIndex": 3, "explain": "", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Khoảng cách từ $D$ đễn mặt phẳng $( S B C )$ bằng:", "choices": ["$\\dfrac{a \\sqrt{3}}{3}$", "$\\dfrac{2 a \\sqrt{3}}{3}$", "$2 a$", "$a$"], "correctIndex": 1, "explain": "", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Khoảng cách giữa hai đường thẳng $S D, A B$ bằng:", "choices": ["$\\dfrac{a \\sqrt{3}}{3}$", "$\\dfrac{2 a \\sqrt{3}}{3}$", "$\\dfrac{2 a \\sqrt{5}}{5}$", "$a$"], "correctIndex": 2, "explain": "", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Thể tích khối chóp $S . A B C D$ bằng:", "choices": ["$\\dfrac{2 \\sqrt{2} a^3}{3}$", "$\\dfrac{\\sqrt{2} a^3}{3}$", "$\\dfrac{3 \\sqrt{2} a^3}{2}$", "$a^3$"], "correctIndex": 0, "explain": "", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Diện tích hình thang $ABCD$ là", "choices": ["$ {a}^2$", "$2 {a}^2$", "$3 {a}^2$", "$4 {a}^2$"], "correctIndex": 2, "explain": "", "nguon": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Khoảng cách từ đỉnh $S$ đến $ABCD$ là", "choices": ["$\\dfrac{3 {a}}{5}$", "$\\dfrac{\\sqrt{15} {a}}{3}$", "$\\dfrac{3 \\sqrt{15} {a}}{5}$", "$\\dfrac{\\sqrt{15} {a}}{5}$"], "correctIndex": 2, "explain": "", "nguon": ""}]}];
